import {axiosInstance} from './globalInstance'

class DeleteSessionApi {
  static async deleteSessionFromId (data, appId) {
    return axiosInstance({
      method: 'DELETE',
      url: `${process.env.API_URL  }/app/${  appId  }/session`,
      data,
      withCredentials: true
    })
  }

  static async deleteUserSession (data) {
    return axiosInstance({
      method: 'POST',
      url: `${process.env.DB_API_URL}/deletion_requests`,
      data,
      withCredentials: true
    })
  }
}

export default DeleteSessionApi
