import Delete from 'services/deleteSessionApi'
import { getCsrf } from './common'

export const deleteSessionFromId = (data, appId) => async (dispatch) => {
  const csrf = await dispatch(getCsrf())
  data['_csrf'] = csrf
  return Delete.deleteSessionFromId(data, appId).then(res => res.data).catch(error => error)
}

export const deleteUserSession = (data) => async () => {
  return Delete.deleteUserSession(data).then(res => res.data).catch(error => error)
}
