import React, { useEffect } from 'react'
import { WarningOutlined } from '@ant-design/icons';
import { useDispatch, useSelector } from 'react-redux'
import MapWithAMarkerClusterer from 'components/common/map'
import { getLocationData } from 'redux/actions/userList'

const LocationContent = ({ urlQ, setLoader }) => {
  const { dateSegment } = useSelector(( state ) => state.appFilter)
  const locationData = useSelector( 
    ({ userDetailReducer }) => userDetailReducer.locationData
  )
  const dispatch = useDispatch()
  const {uxcamuserid} = urlQ
  const callApi = async () => {
    setLoader(true)
    dispatch(
      getLocationData()
    )
    setLoader(false)
  }
  useEffect(() => {
    callApi()
  }, [ dateSegment, uxcamuserid])

  return (
    <div className='map-card'>
      {locationData ? (
        locationData.map.length ? (
          <MapWithAMarkerClusterer markers={locationData.map} />
        ) : (
          <p className='dashboard-nqi-error-box'>
            <WarningOutlined /> During this time no session was recorded
          </p>
        )
      ) : (
        <></>
      )}
    </div>
  );
}
export default React.memo(LocationContent)
