import React, { useState, useEffect, useRef } from 'react'

import {  useDispatch } from 'react-redux'
import { reject, findLastIndex, map } from 'lodash'
import { fetchPlanHatApi } from 'redux/actions/common'

import ReactLoader from 'components/common/reactLoading';
import Wrapper from 'components/common/Customary/Wrapper'
import LoaderAdvanced from 'components/common/LoaderAdvanced';
import StatisticsGraphV2 from 'components/common/StatisticsGraph'
import PendingLoaderInfo from 'components/common/PendingLoaderInfo'
import CategoryLevelDropdown from 'components/common/CategoryLevelDropdown'

import CustomExportGraphDropdown from 'Utils/helpers/CustomExportGraphDropdown'

const insideLoader = (
  <>
    <PendingLoaderInfo preText="Computing chart data" />
    <ReactLoader />
  </>
)
const removeValue = (array, id) => reject(array, (item, index) =>
     index === id // or some complex logic
  )
const GroupbyDropdown = ({
  selectedCategory,
  bottomBarClassFlag,
  callGraphApi,
  graphData,
  loader = false,
  box_key,
  commonLoader,
  labelDisplay
}) => {
  const dispatch = useDispatch()
  const chartRef = useRef()
  const [grpByVal, set_grpByVal] = useState(null)
  const options = selectedCategory ? selectedCategory['gb_l'] : null
  const populateOptions = () => {
    let groupby_default = selectedCategory && selectedCategory['groupby_default']
    set_grpByVal(groupby_default)
  }
  const delGrpByArr = async (index) => {
    const removedGrpByDefault = removeValue(grpByVal, index)
    selectedCategory['groupby_default'] = removedGrpByDefault
    await callGraphApi(selectedCategory)
    set_grpByVal(removedGrpByDefault)
  }
  const handleGrpBy = async (
    display,
    id,
    index,
    isEnterKeyPress,
    operator,
    categoryTitle,
    attribute,
    isShowTopActivated,
    maxGroupNumber,
    labels
  ) => {
    if (
      !isShowTopActivated ||
      (maxGroupNumber === 500 && attribute !== 'session_sessionid')
    ) maxGroupNumber = 50
    if (!labels.length) labels = undefined
    const selectedCategoryByTitle = options[categoryTitle]
    const indexBySelectedCategory = findLastIndex(selectedCategoryByTitle, {
      attribute,
    })
    if (indexBySelectedCategory > -1) {
      const data = selectedCategoryByTitle[indexBySelectedCategory]
      data['max_group_number'] = maxGroupNumber
      data['labels'] = labels
      grpByVal[index] = data
      selectedCategory['groupby_default'] = grpByVal
      await callGraphApi(selectedCategory)
      set_grpByVal(grpByVal)
    }
    dispatch(fetchPlanHatApi({ action: `Changed user journey grouping ${index + 1}`, info: { 'group type':  attribute} }))
  }
  useEffect(() => {
    populateOptions()
  }, [selectedCategory])
  return (
    <>
      <div className='stat-filter-bar'>
        <div className='filter-left-box'>
          <h4>{selectedCategory ? selectedCategory.box_name : ''}</h4>
          <div className='dropdown-wrapper'>
            <div className='big-combo-box'>
              {grpByVal && grpByVal.length
                ? map(grpByVal, (value, indx) => (
                      <Wrapper
                        label={indx === 0 ? 'Group by' : 'and'}
                        key={value.attribute}
                        filterArr={delGrpByArr}
                        _grpByArr={grpByVal}
                        _index={indx}
                        isRevamped
                        _idByArr="grp-array"
                        dataIntercomTarget={indx === 0 ? 'Group by' : 'and'}
                      >
                        <CategoryLevelDropdown
                          handleChangeEvents={handleGrpBy}
                          key={value.attribute}
                          id="groupby_dropdown"
                          options={options}
                          eventProperty={false}
                          userProperty={false}
                          eventDropVal={value}
                          _idByArr="grp-array"
                          indexByGrpby={indx}
                          group_list={grpByVal}
                          isUserJourney
                          isRevamped
                          selectedCategory={selectedCategory}
                          attribute={value.attribute}
                        />
                      </Wrapper>
                    ))
                : null}
              {grpByVal && grpByVal.length < 2 ? (
                <Wrapper label="and" isRevamped className='add-btn'>
                  <CategoryLevelDropdown
                    handleChangeEvents={handleGrpBy}
                    key={grpByVal[0].attribute}
                    id="groupby_dropdown"
                    options={options}
                    eventProperty={false}
                    userProperty={false}
                    _idByArr="grp-main"
                    placeholderText="+ Add grouping"
                    indexByGrpby={1}
                    group_list={grpByVal}
                    isUserJourney
                    isRevamped
                    selectedCategory={selectedCategory}
                    attribute={grpByVal[0].attribute}
                  />
                </Wrapper>
              ) : null}
            </div>
          </div>
        </div>
        <div className='filter-right-box'>
          <Wrapper>
            <CustomExportGraphDropdown chartRef={chartRef} graphData={graphData} />
          </Wrapper>
        </div>
      </div>
      <LoaderAdvanced
        show={commonLoader ? false : loader}
        message={insideLoader}
        backgroundStyle={{
          backgroundColor: 'rgba(255,255,255,0.3)',
        }}
        style={{ height: '100%' }}
      >
        <StatisticsGraphV2
          box_key={box_key}
          graphData={graphData}
          height={bottomBarClassFlag ? 'calc(100vh - 230)' : `calc(100vh - ${labelDisplay ? '543' :'503'}px)`}
          chartRef={chartRef}
        />
      </LoaderAdvanced>
    </>
  )
}
export default GroupbyDropdown
