import React from 'react';
import Link from 'next/link'
import { useDispatch } from 'react-redux';
import { toLower } from 'lodash';
import { fetchPlanHatApi } from 'redux/actions/common';
import { RedirectLinkSVG } from '../svg_files'

const LinkToNewTab = (props) => {
  const { label, href, link } = props
  const dispatch = useDispatch()
  return (
    <Link
      href={href}
      as={link}
      passHref
      legacyBehavior
    >
      <a onClick={ () => dispatch(fetchPlanHatApi({ action: `View all user ${toLower(label)} user details page` })) } target="_blank" rel="noreferrer">
        <>
          <span>{label}<RedirectLinkSVG /></span>
        </>
      </a>
    </Link>
  )
}

export default LinkToNewTab
