/* eslint-disable react/jsx-props-no-spreading */
import React, { useCallback, useMemo, useState } from 'react';
import { Button, Menu, Dropdown, message } from 'antd';
import styled from 'styled-components';

import { DownLoadIcon } from 'components/shared/Sessions/DetailSideBar/IconSvg/index';

import { useCheckExportPlan } from 'hooks/useCheckExportPlan';
import DownloadDataModal from './DownloadDataModal';


const MenuItem = Menu.Item;

const DownLoadIconButton = styled(Button)`
  padding: 0;
  display: flex;
  justify-content: center;
  align-content: center;
  height: fit-content;
  padding: 6px 10px;
  height: 32px;
  border-radius: 4px;
  border-color: #828282;
  margin-left: 20px;
  background-color: #ffffff;

  svg {
    path,
    rect {
      fill: #828282;
      stroke: #828282;
    }
  }
  &:hover {
    background: transparent;
    svg {
      path,
      rect {
        fill: #5d97ff;
        stroke: #5d97ff;
      }
    }
  }
`;

const TitleDiv = styled.div`
  color: #5d97ff;
  font-weight: 700;
  font-size: 14px;
  line-height: 24px;
  padding: 2px 12px;
  margin-bottom: 2px;
`;

const StyledMenu = styled(Menu)`
  border-radius: 4px;
  padding: 4px;
  .ant-dropdown-menu-item {
    display: flex;
    align-items: center;
    font-weight: 400;
    line-height: 24px;
    font-size: 12px;
    color: #161e35;
    svg {
      width: 13px;
      display: inline-flex;
      margin-right: 2px;
    }
    :hover {
      background-color: #eff5ff;
      border-radius: 4px;
    }
  }
`;

/* globalFilter is passed only in case of screen page. It is the screen filter by name in client side  */

const Download = ({ globalFilter }) => {
  const [visibleDownloadModal, setVisibleDownloadModal] = useState(false);
  const [downLoadColumn, setDownloadColumn] = useState();
  const {canExportData, isApiError, apiError, CommonUpgradeModal, upgradePlan, setUpgradePlan} = useCheckExportPlan();

  const handleVisibleModal = (visibleFlag) => {
      setVisibleDownloadModal(visibleFlag);
  };

  const handleDownLoadOption = useCallback(({ key }) => {
    if (apiError?.response?.data?.error || isApiError) {
      message.error(
        apiError?.response?.data?.error?.message || 'Something went wrong'
      );
      return;
    }

    if (canExportData) {
      setDownloadColumn(key);
      setUpgradePlan(false);
      handleVisibleModal(true);
    } else {
      setUpgradePlan(true)
    };
  }, [apiError?.response?.data?.error, canExportData, isApiError, setUpgradePlan]);

  const modalProps = {
    visibleDownloadModal,
    handleVisibleModal,
    downLoadColumn,
    setDownloadColumn,
    globalFilter
  };

  const menu = useMemo(
    () => (
      <StyledMenu onClick={handleDownLoadOption}>
        <TitleDiv>Download data as</TitleDiv>
        <MenuItem key="visibleOnly">
          <DownLoadIcon /> Visible columns only (CSV)
        </MenuItem>
        <MenuItem key="allColumns">
          <DownLoadIcon /> All columns (CSV)
        </MenuItem>
      </StyledMenu>
    ),
    [handleDownLoadOption]
  );

  return (
    <>
      <Dropdown overlay={menu} placement="bottomLeft" trigger={['click']}>
        <DownLoadIconButton
          onClick={(e) => e.preventDefault()}
          icon={<DownLoadIcon />}
        />
      </Dropdown>
      {
        upgradePlan ? <CommonUpgradeModal /> :
        visibleDownloadModal && <DownloadDataModal {...modalProps} />
      }
    </>
  );
};

export default Download;
