import React, { useMemo, memo } from 'react';

import has from 'lodash/has';
import { Tooltip } from 'antd';
import { useSelector } from 'react-redux';
import { createColumnHelper } from '@tanstack/react-table';

import { AndroidOutlined, AppleOutlined } from '@ant-design/icons';

import { getDifferenceFromNow } from 'Utils/DateConversion/dateConversionUtils';
import { containsOnlyNumbers } from 'Utils/helpers/numberFormatter';
import {
  convertGetTime,
  getRenamedDeviceName,
} from 'Utils/helpers/commonUtils';
import { getOsIcon } from 'components/common/SessionTableUtil';

import TableCheckbox from 'components/features/issues/components/ReactTable/TableCheckbox';
import { removeUxCamCustomProperty, stripCustomPropertyAndMapLabel } from 'components/common/ColumnUpdate/utils';
import { getUserId } from 'Utils/helpers/userIdUtils';
import TableRowCheckCell from '../TableRowCheckCell';

import {
  Cell,
  HorizontalCell,
  StyledName,
  EllipseText,
  EllipseTitle,
  CheckBoxWrapper,
  CellWrapper,
} from '../styles';

const platformDisplayMapper = {
  1: 'Android',
  2: 'iOS',
  3: 'Desktop',
}

const TotalSession = memo(({ row }) => {
  const { totalSession } = row?.original;
  return (
    <Cell>
      <div>{containsOnlyNumbers(totalSession)}</div>
    </Cell>
  );
});

const UserName = memo(({ row }) => {
  const { city } = row?.original;
  const userIdConfig = getUserId({
    customUserId: row?.original?.kUXCam_UserIdentity,
    uxcamuserid: row.original?.uxcamuserid,
  });
  return (
    <HorizontalCell>
      <div className="userName">
        {!userIdConfig?.customUserId ? (
          <Tooltip
            placement="topLeft"
            title={
              <span>
                {userIdConfig?.info}
              </span>
            }
          >
            <StyledName className="title text-italic-asterisk">
              {userIdConfig?.uxcamuserid}
            </StyledName>
          </Tooltip>
        ) : (
          <StyledName className="title">
            {userIdConfig?.customUserId}
          </StyledName>
        )}
        <span className="subtitle">{city}</span>
      </div>
    </HorizontalCell>
  );
});

const DeviceId = memo(({ row }) => {
  const { deviceid } = row?.original;
  return (
    <HorizontalCell>
      <div>{deviceid}</div>
    </HorizontalCell>
  );
});

const Device = memo(({ row }) => {
  const { platform, deviceModel } = row?.original;
  const deviceModelFormatted = deviceModel?.includes('iPhone')
    ? getRenamedDeviceName(deviceModel)
    : deviceModel?.toUpperCase();
  return (
    <HorizontalCell>
      <div className="platform-icon">
        {platform === 1 ? <AndroidOutlined /> : <AppleOutlined />}
      </div>
      <div>{deviceModelFormatted}</div>
    </HorizontalCell>
  );
});

