const EngagementTime = memo(({ row }) => {
  const { engagementTime } = row?.original;
  return (
    <Cell>
      {engagementTime && (
        <div>
          {engagementTime < 60
            ? `${Math.round(engagementTime)} sec`
            : convertGetTime({ durationInSecs: engagementTime })}
        </div>
      )}
    </Cell>
  );
});

