const TableHeader = memo(({ header }) => {
  const { attribute, title, subTitle, isCustomUserProperty } = header;

  if (isCustomUserProperty) {
    return (
      <EllipseTitle>
        <em>{ stripCustomPropertyAndMapLabel(title) }</em>
      </EllipseTitle>
    );
  }

  return (
    <EllipseTitle>
      {attribute === 'columndate' ? `${title}${subTitle}` : title}
    </EllipseTitle>
  );
});

const columnsMapper = {
  userName: 'name',
  lastseen: 'lastseen',
  totalsession: 'totalsession',
  engagementtime: 'engagementtime',
  deviceModal: 'devicemodel',
  osVersion: 'osversion',
  appVersion: 'appversion',
  screencount: 'screencount',
  eventcount: 'eventcount',
  totalgesture: 'totalgesture',
  firstseen: 'firstseen',
  deviceid: 'deviceid',
  ragegesturecount: 'ragegesturecount',
  deviceClass: 'deviceclass',
  browserName: 'browsername',
  browserVersion: 'browserversion',
  deviceType: 'devicetype',
  deviceHeight: 'deviceheight',
  deviceWidth: 'devicewidth',
  deviceOsName: 'deviceosname',
};

const CellMapper = {
  [columnsMapper.userName]: UserName,
  [columnsMapper.lastseen]: LastSeen,
  [columnsMapper.totalsession]: TotalSession,
  [columnsMapper.engagementtime]: EngagementTime,
  [columnsMapper.screencount]: ScreenCount,
  [columnsMapper.deviceModal]: Device,
  [columnsMapper.ragegesturecount]: RageGestureCount,
  [columnsMapper.eventcount]: EventCount,
  [columnsMapper.appVersion]: AppVersion,
  [columnsMapper.totalgesture]: TotalGesture,
  [columnsMapper.firstseen]: FirstSeen,
  [columnsMapper.deviceid]: DeviceId,
  [columnsMapper.osVersion]: OSVersion,
  [columnsMapper.deviceClass]: DeviceClassInfo,
  [columnsMapper.browserName]: Browser,
  [columnsMapper.browserVersion]: BrowserVersion,
  [columnsMapper.deviceType]: DeviceType,
  [columnsMapper.deviceHeight]: DeviceHeight,
  [columnsMapper.deviceWidth]: DeviceWidth,
  [columnsMapper.deviceOsName]: DeviceOs,
};

const CustomPropsCellRender = memo(({ cell, row }) => {
  const {
    column: { id },
  } = cell;
  const { userProperty } = row?.original;

  const value = has(userProperty, removeUxCamCustomProperty(id)) ? userProperty[removeUxCamCustomProperty(id)] || 'N/A' : 'N/A';
  return (
    <Cell>
      <EllipseText>{containsOnlyNumbers(value.toString())}</EllipseText>
    </Cell>
  );
});

export const useUserColumns = ({ headers }) => {
  const {
    urlReducer: { uxcamuserid: rawUxcamUserId },
  } = useSelector((state) => state);
  const columnHelper = createColumnHelper();
  const isUxcamUserId = /^[a-zA-Z0-9-]*$/.test(rawUxcamUserId);
  const uxcamUserId = useMemo(() => (isUxcamUserId ? rawUxcamUserId : undefined), [isUxcamUserId, rawUxcamUserId]);

  const columns = useMemo(
    () =>
      (headers)
        .map((header) => {
          const {
            isVisible,
            attribute,
            title,
            titleInfo: tooltipInfo,
            smallUserTable,
            isSortable,
            isCustomUserProperty,
          } = header;
          return isVisible && (uxcamUserId ? smallUserTable : true)
            ? columnHelper.accessor(attribute, {
                header: (
                  <Tooltip title={tooltipInfo}>
                    <CellWrapper>
                      <TableHeader header={header} />
                    </CellWrapper>
                  </Tooltip>
                ),
                accessor: attribute,
                titleInfo: tooltipInfo,
                cell: isCustomUserProperty
                  ? CustomPropsCellRender
                  : CellMapper[attribute] || '',
                width:
                  // eslint-disable-next-line no-nested-ternary
                  attribute === 'sessionhashofuser'
                    ? 180
                    : attribute === 'event_name'
                    ? 150
                    : 120,
                enableSorting: isSortable,
                minWidth: attribute === 'event_name' ? 120 : 100,
                key: title,
                isCustomUserProperty,
              })
            : null;
        })
        .filter((el) => el),
    [headers, uxcamUserId]
  );

  const columnsWithSelect = useMemo(() => [
    {
      id: 'select',
      disableResizing: true,
      minWidth: 35,
      width: 35,
      maxWidth: 35,
      header: ({ table }) => (
        <CheckBoxWrapper>
          <TableCheckbox
            {...{
              checked: table.getIsAllRowsSelected(),
              indeterminate: table.getIsSomeRowsSelected(),
              onChange: table.getToggleAllRowsSelectedHandler(),
            }}
          />
        </CheckBoxWrapper>
      ),
      cell: ({ row }) => (
        <TableRowCheckCell
          row={row}
        />
      ),
    },
    ...columns,
  ], [columns]);

  return columnsWithSelect;
};
