//         userAnalyticsReducer: { statsBoxes },
//     } = useSelector((state) => state);

//     return statsBoxes && <UserStatisticsCards />;
// });

const UserPageNew = ({ userData, loading, resetPageDataWithApiCall, statsLoader, handleSortByOrder, orderBy }) => {

  const {
    urlReducer: urlQuery,
  } = useSelector((state) => state);

  const bottomRef = useRef(null);
  const topRef = useRef(null);

  const { uxcamuserid: rawUserId } = urlQuery;

  const isUxcamUserId = /^[a-zA-Z0-9-]*$/.test(rawUserId);
  const uxcamuserid = useMemo(() => (isUxcamUserId ? rawUserId : undefined), [isUxcamUserId, rawUserId]);

  const scrollToBottom = () => {
    bottomRef?.current && bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  };

  const scrollToTop = () => {
    topRef?.current && topRef.current?.scrollIntoView({ behavior: 'smooth' })
  };
  useEffect( ()=> {
    if(uxcamuserid){
      scrollToBottom()
    } else {
      scrollToTop()
    }
  },[uxcamuserid]);

  const sortByTransform = (sort) => {
    if (sort.length > 0) {
      const { sortName, sortOrder, isCustomUserProperty } = sort[0];
      return [{
        id: sortName,
        desc: sortOrder === 'desc',
        ...isCustomUserProperty && { isCustomUserProperty },
      }]
    }
    return []
  }
  return (
    <Wrapper expanded={Boolean(!uxcamuserid)}>
      <div className="top" ref={topRef} />
      {/* <UserStatisticsCardsWrapper/>  */}
      <UserToolbar
          expanded={Boolean(!uxcamuserid)}
          statsLoader={statsLoader}
          resetPageDataWithApiCall={resetPageDataWithApiCall}
          headers={userData?.header}
        />
      <Main expanded={Boolean(uxcamuserid)}>
        <>
        <UserList
              expanded={Boolean(uxcamuserid) || false}
              data={userData}
              isLoading={loading}
              setSortedBy={handleSortByOrder}
              sortedBy={
                orderBy?.length > 0
                    ? orderBy
                    : sortByTransform(userData?.orderBy || [])
              }
          />
          {uxcamuserid && (
              <UserDetail
                 resetPageDataWithApiCall={resetPageDataWithApiCall}
                 tableData={userData}
              />
          )}
          <div className="bottom" ref={bottomRef} />
        </>
      </Main>
    </Wrapper>
  );
};

export default memo(UserPageNew);
