import React, {useState,  useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { Col } from 'antd'
import { getUserDetail } from 'redux/actions/userList'
import { theme } from 'theme'
import styled from 'styled-components'
import UsersDetailsBox from './UsersDetailsBox'

const UserDetailWrapper = styled.div`
   .userinfo-box-wrapper{
      background-color: ${theme.colors.primarySnow};
      position: relative;
      border: 1px solid ${theme.colors.surface10};
      height: 100%;
      display: flex;
      flex-direction: column;
      .tab-body-wrapper{
        flex: 1;
      }

      .screen-page-wrapper{
        margin: 0;
        border: none;
      }
    }
    .userinfo-box-wrapper .session-sidebar-right .screen-session-table-sm,
    .userinfo-box-wrapper .session-sidebar-right .screen-session-table-sm .table-wrap .fixedDataTableLayout_main.public_fixedDataTable_main,
    .userinfo-box-wrapper .session-sidebar-right .screen-session-table-sm .table-wrap .fixedDataTableLayout_rowsContainer{
        height: calc(100vh - 166px) !important
    }
    .user-details{
      margin: 40px 0 0 10px;
      display: flex;
      width: calc(100vw - 582px);;
      height:calc(100% - 40px);
      .user-sm-table{
          width: 400px !important;
      }
      .Loader{
          width:100%;
          .Loader__content{
              height: calc(100% + 40px); 
          }
      }
    }

    .journey-tab-wrapper{
      height: 100%;
      display: flex;
      flex-direction: column;
      .journey-graph-wrapper{
        flex: 1;
      }
    }
`

const UserDetail = ({ resetPageDataWithApiCall, tableData }) => {
  const dispatch = useDispatch();
  const { urlReducer: urlQuery, appFilter, userDetailReducer: userDetail, errorReducer: error } = useSelector(state => state);
  const userSegment = appFilter?.user?.segment;
  const { labelDisplay } = userDetail;
  const {uxcamuserid } = urlQuery

  const [loader, setLoader] = useState(false)
  const callUserDetailsApi = async (userId) => {
    setLoader(true)
    dispatch(getUserDetail(userId)).then(() => setLoader(false))
  }
  useEffect(() => {
    uxcamuserid && callUserDetailsApi(uxcamuserid)
  }, [uxcamuserid])

  const renderComponent =
    urlQuery.type === 'detailsOnly' ? (
      <Col sm={24} lg={24}>
        <UsersDetailsBox
          urlQuery={urlQuery}
          userDetail={userDetail}
          userSegment={userSegment}
          error={error}
          loader={loader}
          setLoader={setLoader}
          resetPageDataWithApiCall={resetPageDataWithApiCall}
          tableData={tableData}
        />
      </Col>
    ) : (
      <div className={`user-details ${labelDisplay ? 'user-label-expand' : ''}`}>
          <UsersDetailsBox
            urlQuery={urlQuery}
            userDetail={userDetail}
            userSegment={userSegment}
            error={error}
            loader={loader}
            setLoader={setLoader}
            resetPageDataWithApiCall={resetPageDataWithApiCall}
            tableData={tableData}
          />
      </div>
    )
  return (
    <UserDetailWrapper>
      {renderComponent}
    </UserDetailWrapper>
  )
}
export default UserDetail
