/* eslint-disable no-nested-ternary */
import React, { memo } from 'react';
import { map, isNull, isArray, isObject } from 'underscore'
import { InfoCircleOutlined } from '@ant-design/icons';
import { Card, Tooltip } from 'antd';
import { v4 } from 'uuid'
import { capitalize } from 'lodash'
import { getRenamedDeviceName } from 'Utils/helpers/commonUtils';
import { readableTimeFormatter } from 'Utils/DateConversion/dateConversionUtils';

const WebSDKOnlyNames = [
  'Browser name',
  'Browser version',
  'Device type',
  'OS name',
  'Initial landing page',
  'Initial referrer',
  'Initial referrer domain',
  'Initial landing UTM'
]
const readableUtmFormatter = (utm) => {
  if (!utm) return '';
  const utmObj = JSON.parse(utm);
  return (
    <div>
      {Object.entries(utmObj).map(([key, value]) => (
        <div key={key}>
          <span style={{ fontWeight: 500 }}>{key}: </span>
          <span>{value}</span>
        </div>
      ))}
    </div>
  );
}

const PropertiesContent = ({ userDetails, isWebSDK = false }) => {
  const { properties } = userDetails;
  return (
    <div className='property-wrapper custom-scrollbar'>
    <div className='property-wrap-height'>
      {map(properties, (value, key) => (
        <Card key={v4()}>
          <table className='table'>
            <tr>
              <th colSpan={key}>{capitalize(key)}</th>
            </tr>
            {map(value, (x, i) => {
              let array
              if (key === 'events') {
                array = x
              } else array = x.value
              return isObject(array) || isArray(array)
                ? map(array, (_value, _key) => {
                  if (typeof _key !== 'number' && _value === 'n/a')
                    _value = <em>n/a</em>
                  if (typeof _key === 'number') _key = true
                  return _key && (
                    <tr key={v4()}>
                      <td>
                        <div className='title'>
                          {key === 'events' ? _value.eventname : _key}
                          <Tooltip
                            title={
                              key === 'events'
                                ? _value.eventname === 'ANR'
                                  ? 'Application Not Responding'
                                  : _value.eventname === 'rageTap'
                                    ? 'Count of rage taps'
                                    : `Coded events: ${_value.eventname}`
                                : x.tooltip
                            }
                          >
                            <InfoCircleOutlined style={{ paddingLeft: 5 }} />
                          </Tooltip>
                        </div>
                      </td>
                      <td style={{ padding: '0 10px' }}>:</td>
                      <td className='value'>
                        <div className='text-truncate'>
                          {key === 'events'
                            ? _value.count
                            : typeof _value === 'boolean'
                              ? `${_value}`
                              : _value}
                        </div>
                      </td>
                    </tr>
                  );
                })
                : x.name && (
                  WebSDKOnlyNames.includes( x.name ) && !isWebSDK ? null :
                  <tr key={v4()}>
                    <td>
                      <div className='title'>
                        {x.name}
                        <Tooltip title={x.tooltip}>
                          <InfoCircleOutlined style={{ paddingLeft: 5 }} />
                        </Tooltip>
                      </div>
                    </td>
                    <td style={{ padding: '0 10px' }}>:</td>
                    <td className='value'>
                      <div className='text-truncate'>
                        {key === 'user' && i === 0 ? (
                          <span>
                            {x.value || <em>not assigned</em>}
                            <span
                              style={{
                                marginLeft: '10px',
                                color: '#5D97FF',
                                fontSize: '11px',
                              }}
                            >
                              (
                              <a
                                target="_blank"
                                href="https://help.uxcam.com/en/articles/10222539-ideas-for-custom-user-properties"
                                style={{ textDecoration: 'underline' }} rel="noreferrer"
                              >
                                API documentation
                              </a>
                              )
                            </span>
                          </span>
                        ) : x.value === 'n/a' ? (
                          <em>n/a</em>
                        ) : typeof x.value === 'boolean' ? (
                          `${x.value}`
                        ) : x.name === 'Number of events' &&
                          isNull(x.value) ? (
                          0
                        ) : x.name === 'Device class' || x.name === 'Device manufacturer' ? 
                          getRenamedDeviceName(x.value)
                        : x.name === 'Time spent in the app' ? 
                            readableTimeFormatter(x.value)
                        : x.name === 'Initial landing UTM' ? 
                          readableUtmFormatter(x.value)
                        :x.value}
                      </div>
                    </td>
                  </tr>
                );
            })}
          </table>
        </Card>
      ))}
    </div>
  </div>
  )
}
export default memo(PropertiesContent)
