/* eslint-disable camelcase */
import React, { useMemo } from 'react'
import {
  ClockCircleOutlined,
  EnvironmentOutlined,
  UserOutlined,
} from '@ant-design/icons';

import {  Tooltip, Badge } from 'antd';
import { useDispatch, useSelector } from 'react-redux'
import styled from 'styled-components';
import LinkHeaderAttribute from 'components/common/LinkHeaderAttribute'
import { displayUserLabel } from 'redux/actions/common';
import { getDate } from 'Utils/DateConversion/dateConversionUtils';
import {LabelIcon} from "components/svg_files";
import { getUserId } from 'Utils/helpers/userIdUtils';

const StyledSpan = styled.span`
font-weight: 500;
`
const DetailsHeaderUser = ({ userSegment, labelDisplay }) => {
  const dispatch = useDispatch()
  const {data : userDetails } =  useSelector(state => state.userDetailReducer)

  const { uxcamuserid, info, customLabel, kuxcam_useridentity  } = userDetails
  const userIdConfig = getUserId({
              customUserId: kuxcam_useridentity,
              uxcamuserid
          });
  let userSessionTooltipData
  if (!userIdConfig?.customUserId) {
    userSessionTooltipData = (
      <span>
          {userIdConfig?.info}
      </span>
    )
  } else {
    userSessionTooltipData = null
  }

  const handleLabelDisplay = () => {
    dispatch(displayUserLabel(!labelDisplay))
  };

  const titleLocation = `${(!info.city || info.city !== 'N/A') ? info.city : 'Undetermined City'}, ${info.country}`
  const tooltipTitleLocation = `Location is ${
    !info.city || info.city === 'N/A' ? 'undetermined city' : info.city
  }, ${info.country || 'N/A'}`

  const totalUserCustomLabel = useMemo(()=> customLabel?.length, [customLabel?.length])

  return ( <div className='page-main-title custom-scrollbar'>
  <div className='data-list-wrapper'>
    <ul className='data-list'>
      <li>
        <UserOutlined />
        <LinkHeaderAttribute
          segment={userSegment}
          _attribute="uxcamuserid"
          __value={userDetails.uxcamuserid}
          tooltipTitle_value={userSessionTooltipData}
          isClickableLink={false}
          table='appuser'
        >
         {!userIdConfig?.customUserId ? <StyledSpan className="text-italic-asterisk">  {userIdConfig?.uxcamuserid}</StyledSpan> : <StyledSpan>  {userIdConfig?.customUserId}</StyledSpan>}
        </LinkHeaderAttribute>
      </li>
      <li aria-hidden = 'true' onClick={handleLabelDisplay} className="labels-nav">
        <Tooltip overlayClassName="user-label-tooltip" title="User Labels" placement="bottom">
          <LabelIcon/>Labels<Badge count={totalUserCustomLabel}/>
        </Tooltip>
      </li>
      <li>
        <EnvironmentOutlined />
        <LinkHeaderAttribute
          segment={userSegment}
          _attribute={
            !info.city || info.city === 'N/A' ? 'device_country' : 'device_city'
          }
          __value={
            !info.city || info.city === 'N/A' ? info.country : info.city
          }
          tooltipTitle_value={tooltipTitleLocation}
          isClickableLink
          table='session'
        >
          {titleLocation}
        </LinkHeaderAttribute>
      </li>
      <li>
        <ClockCircleOutlined />
        <LinkHeaderAttribute
            segment={userSegment}
            _attribute="user_first_seen_on"
            tooltipTitle_value={`First session was at ${getDate(new Date(info.firstSeen), "dd.MM.yyyy")}`}
            __value={
              info.firstSeen
            }
            _operator="on"
            _isNotArrayFormat
            isClickableLink
            table="appuser"
        >
          First seen : {getDate(new Date(info.firstSeen), "dd.MM.yyyy")}
        </LinkHeaderAttribute>
      </li>

      <li>
        <ClockCircleOutlined />
        <LinkHeaderAttribute
          segment={userSegment}
          _attribute="user_last_seen_on"
          tooltipTitle_value={`Last session was at ${getDate(new Date(info.lastSeen), "dd.MM.yyyy")}`}
          __value={
            info.lastSeen
          }
          _operator="on"
          _isNotArrayFormat
          isClickableLink
          table="appuser"
        >
          Last seen : {getDate(new Date(info.lastSeen), "dd.MM.yyyy")}
        </LinkHeaderAttribute>
      </li>
    </ul>
  </div>
  </div>)
   
  ;
}

export default DetailsHeaderUser
