import React, { useCallback, useEffect, useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import moment from 'moment/moment'
import {
  getUserJourneyBoxes,
  getDropdownOptions,
  getUserJourneyGraph,
} from 'redux/actions/userList'
import { useIsAppType } from 'hooks/useIsAppType'
import { getTimezoneOffset } from 'Utils/DateConversion/dateConversionUtils'
import UserJourneyInfoBoxes from './UserJourneyInfoBoxes'
import GroupbyDropdown from './GroupbyDropdown'
import UserDetailCalendar from './UserDetailCalendar';

const defaultDateRange = {
  attribute: 'upload_time',
  operator: 'between_dates',
  value: {
    lower: moment.utc().subtract(1, 'months').format(),
    upper: moment.utc().format()
  },
  label: 'Last 1 month'
}

const UserJourney = ({ loader, bottomBarClassFlag = false }) => {
  const dispatch = useDispatch()
  const { userDetailReducer, appFilter, urlReducer } = useSelector(
    (state) => state
  )
  const {
    userJourneyBoxes,
    userJourneyOptions,
    userJourneyGraphData: graphData,
    loaderForGraph,
    loaderForBoxes,
    labelDisplay
  } = userDetailReducer
  const { appId, uxcamuserid} = urlReducer
  const { dateSegment } = appFilter

  const [dateRangeState, setDefaultDateRange] = useState(defaultDateRange)
  const [selectedCategory, setSelectedCategory] = useState(null)
  const isWebApp = useIsAppType( 'web' );

  const callUserJourneyApi = useCallback( async (dateRange) => {
    const payload = {
      appid: appId,
      filters: appFilter.user.segment,
      date_range: dateRange || dateRangeState,
      uxcamuserid
    }
    uxcamuserid && dispatch(getUserJourneyBoxes(payload))
  }, [appFilter.user.segment, dateRangeState, dispatch, appId, uxcamuserid])

  const callGraphApi = useCallback( async (
    { agg_l: aggL, fb_l: fbL, groupby_default: groupbyDefault, box_key: boxKey },
    dateRange
  ) => {
    // fb_l: list of filter
    // agg_l: list of aggregation
    let indexByGrp
    const appid = urlReducer.appId
    const updatedFbl = fbL.filter(item => item.attribute !== 'date_range')
    updatedFbl.map((v, i) => {
      if (i === 0) v.value = [urlReducer.uxcamuserid]
    })
   if (boxKey === 'total_engagement') {
      indexByGrp = _.findLastIndex(groupbyDefault, {
        attribute: 'session_sessionid',
      })
      if (indexByGrp >= 0) groupbyDefault[indexByGrp].max_group_number = 500
    }
    const dateRangeModified = {
      ...(dateRange || dateRangeState),
      timezoneOffset: getTimezoneOffset((dateRange || dateRangeState)?.tz, new Date())
    }
    // * CX-2255 -add timezone offset to groupByList
    const modifiedGroupList = groupbyDefault.map((item) => {    
            return {
                ...item,
                time_zone_offset: getTimezoneOffset(dateRangeModified.tz, new Date())
            }
    })

    const payload = {
      appid,
      aggregation_list: aggL,
      group_list: modifiedGroupList,
      date_range: dateRangeModified,
      filters: [...updatedFbl],
      series_plot_options: {},
    }
    uxcamuserid && dispatch(getUserJourneyGraph(payload))
  }, [dateRangeState, dispatch, urlReducer.appId, urlReducer.uxcamuserid, uxcamuserid])
  const changeDateChange = useCallback(async (dateRange = defaultDateRange) => {
    await setDefaultDateRange(dateRange)
    callUserJourneyApi(dateRange)
    selectedCategory && callGraphApi(selectedCategory, dateRange)
  }, [callGraphApi, callUserJourneyApi, selectedCategory])

  const callDropdownApi = () => {
    const appid = urlReducer.appId
    const payload = {
      appid,
      webApp: isWebApp,
    }
    dispatch(getDropdownOptions(payload))
  }

  useEffect(() => {
    changeDateChange(dateSegment)
  }, [uxcamuserid, dateSegment])

  useEffect(() => {
    selectedCategory && callGraphApi(selectedCategory)
  }, [selectedCategory])

  useEffect(() => {
    !userJourneyOptions && callDropdownApi()
  }, [])

  return (
    <div className='journey-tab-wrapper'>
      <div className='journey-right-wrapper'>
        <div className='right-fliter-wrap'>
          <div className='date-box'>
            <UserDetailCalendar
              isUserJourney
              defaultDateRange={dateRangeState}
              changeDateChange={changeDateChange}
            />
          </div>
        </div>
      </div>
      <UserJourneyInfoBoxes
        userJourneyBoxes={userJourneyBoxes}
        dropdown_options={userJourneyOptions}
        setSelectedCategory={setSelectedCategory}
        loader={loaderForBoxes}
        urlReducer={urlReducer}
        dateRange={dateRangeState}
      />
      <div className='journey-graph-wrapper'>
        <div className='stat-full-box'>
          <div className='stat-graph-box'>
            <GroupbyDropdown
              selectedCategory={selectedCategory}
              bottomBarClassFlag={bottomBarClassFlag}
              callGraphApi={callGraphApi}
              graphData={graphData}
              uxcamid={urlReducer.uxcamuserid}
              loader={loaderForGraph}
              box_key={selectedCategory && selectedCategory.box_key}
              commonLoader={loader}
              labelDisplay={labelDisplay}
            />
          </div>
        </div>
      </div>
    </div>
  )
}
export default UserJourney
