
import React from 'react';

const { compose, withProps, withHandlers } = require("recompose");
const {
  withScriptjs,
  withGoogleMap,
  GoogleMap,
  Marker,
  OverlayView
} = require("react-google-maps");

const demoFancyMapStyles = require("./googleStyle.json");

const getPixelPositionOffset = (width, height) => ({
  x: -(width / 2),
  y: -(height / 2),
})
const { MarkerClusterer } = require("react-google-maps/lib/components/addons/MarkerClusterer");

const MapWithAMarkerClusterer = compose(
  withProps({
    googleMapURL: "https://maps.googleapis.com/maps/api/js?key=AIzaSyDqUr7-CbNA9BkzJYjK3zqQrUWyHgXq3Kw&v=3.exp&libraries=geometry,drawing,places",
    loadingElement: <div style={{ height: `100%` }} />,
    containerElement: <div className='gmap-box'/>,
    mapElement: <div style={{ height: `100%` }} />,
  }),
  withHandlers({
    onMarkerClustererClick: () => (markerClusterer) => {
      const clickedMarkers = markerClusterer.getMarkers()
    },
  }),
  withScriptjs,
  withGoogleMap
)(props =>
  <GoogleMap
    defaultZoom={ props.markers.length > 0 ? 3:1 }
    defaultCenter={props.markers.length > 0 ?{ lat: parseFloat(props.markers[0].latitude), lng: parseFloat(props.markers[0].longitude) }:{lat: 0, lng: 0}}
    defaultOptions={props.markers.length === 0 ?{ styles: demoFancyMapStyles}:''}
  >
    {props.markers.length > 0 ? <MarkerClusterer
      onClick={props.onMarkerClustererClick}
      averageCenter
      enableRetinaIcons
      gridSize={60}
      maxZoom={15}
    >
      {props.markers.map((marker, i) => <Marker
          key={i}
          position={{ lat: parseFloat(marker.latitude), lng: parseFloat(marker.longitude) }}
        />)}
    </MarkerClusterer>:<OverlayView
      position={{ lat: 0, lng: 0 }}

      mapPaneName={OverlayView.OVERLAY_MOUSE_TARGET}

      getPixelPositionOffset={getPixelPositionOffset}

    >
      <div style={{ background: `white`, border: `1px solid #ccc`, padding: 15, width: '175px', textAlign: 'center' }}>
        <h3>No session location sent</h3>
      </div>
    </OverlayView>}
  </GoogleMap>
);
export default MapWithAMarkerClusterer;
