import React, {
  memo,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import Router from 'next/router';
import { useSelector, useDispatch } from 'react-redux';
import { useQueryClient } from 'react-query';

import { addUserId } from 'redux/actions/common';
import { useCustomLabelApi } from 'hooks/useCustomLabels';
import { DashboardTable, StylesProvider, useFeatureFlag } from 'uxcam-frontend-components';
import { useSessionTableHelper } from '../sessions/SessionDetailsAndVideo/SessionTable/utils';
import { usePagination } from '../issues/components/ReactTable/usePagination';
import { useUserColumns } from './hooks/useUserColumns';

import { UserTableWrapper } from './styles';

  const UserList = ({ expanded, data, isLoading, setSortedBy, sortedBy }) => {
    const {
      currentAppReducer: { _id: appid },
      urlReducer: { userpage, uxcamuserid: uxcamUserId },
      selectedUserReducer: selectedUser,
      appFilter: {
        user: { segment = [] },
      },
    } = useSelector((state) => state);
    const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const {pageChange} = useSessionTableHelper({expanded});
  const { markUserLabel } = useCustomLabelApi();

  const [cachedHeadersData, setCachedHeadersData] = useState([]);
  const [rowselection, setRowSelection] = useState([]);
  const {pagination, setPagination} = usePagination();

  const moveToRef = useRef();
  const prevPaginationRef = useRef();
  const headers = data?.header;


  const columns = useUserColumns({
    headers: headers || cachedHeadersData,
  });

  const userPage = useMemo(() => Number(userpage), [userpage]);
  const newPagination = useMemo(() => data?.pagination ? data?.pagination : prevPaginationRef?.current, [data?.pagination])
  

  const onItemSetActive = useCallback(
    (uxcamuserid, isViewed) => {
        let userQueryKey = ''
        try {
          userQueryKey = ['userList', JSON.parse(localStorage.getItem('usersListReqBody'))] 
        } catch (err) {
          // silent fail
        }
        if (!isViewed) {
        queryClient.setQueryData(userQueryKey, (old) => {
          if ( !old?.data?.data?.body ) {
            return old 
          }
          
          const newBody = old.data.data.body.map((el) => {
            const userDetail = {...el}
            if (el.uxcamuserid === uxcamuserid) {
              userDetail.isViewed = true;
            }
            return userDetail;
        });
        return {
            ...old,
            data: {
                ...old.data,
                data: {
                    ...old.data.data,
                    body: newBody,
                },
            },
        };
         });
        const payload = {
          customLabelName: 'isViewed',
          isTagged: !isViewed,
          labelType: 'user',
          uxcamuserIds: [uxcamuserid],
          appid,
          debugSource: 5
        };
        markUserLabel(payload);
      }
      const url = urlSegmentEncoder(
        `/app/${appid}/users/list/${userPage || 1}/${uxcamuserid}`,
        [...segment]
      );
      const query = `appId=${appid}&parentType=usersList&type=user&uxcamuserid=${uxcamuserid}&userpage=${
        userPage || 1
      }`;
      Router.push(`/integration?${query}`, url);
    },
    [appid, userPage, segment, markUserLabel]
  );

  useEffect(() => {
    if (moveToRef.current && data?.body?.length) {
      let displayUser;
      if (moveToRef.current === 'first') {
        displayUser = { ...data.body[0] };
      } else {
        displayUser = data.body[data.body.length - 1];
      }
      const { uxcamuserid, id, eventPropertyTime } = displayUser;
      if (displayUser) {
        onItemSetActive(uxcamuserid, id, eventPropertyTime, true);
      }
      moveToRef.current = undefined;
    }
  }, [data, onItemSetActive]);

  useEffect(() => {
    if (headers) setCachedHeadersData(headers);
  }, [headers])

  useEffect(() => {
    const selectedRowId = Object.keys(rowselection).map(Number)
    const filteredBody = data?.body?.filter((el, index) => selectedRowId.includes(index))
    const selectedUserIds = filteredBody?.map((el) => el.uxcamuserid)
    dispatch(addUserId(selectedUserIds));
  }, [rowselection])

  useEffect(() => {
    const selectedRowId = Object.keys(rowselection).map(Number);
    if(selectedRowId.length > selectedUser) setRowSelection([]);
  }, [selectedUser])

  useEffect(() => {
    if(newPagination){
      prevPaginationRef.current = newPagination;
    }
  }, [newPagination]);

  const rowsData = useMemo(() => (data?.body?.map(item => ({
    ...item,
    kUXCam_UserIdentity: item?.userProperty?.kUXCam_UserIdentity,
    onItemSetActive: (uxcamuserid, isViewed) => onItemSetActive(uxcamuserid, isViewed),
    onRowClick: (row, e) => {
      const { uxcamuserid, isViewed } = row;
      onItemSetActive(uxcamuserid, isViewed)
    },
    highlightActiveRow: (row) => row.uxcamuserid === uxcamUserId,
  }))), [data?.body, onItemSetActive, uxcamUserId])

  useEffect(() => {
    if (userPage) {
      setPagination((prev) => ({
        ...prev,
        pageIndex: userPage,
      }));
      // to clear out selected values on pagination update
      dispatch(addUserId([]));
    }
  }, [userPage])

  return (
    <UserTableWrapper expanded={expanded}>
      <StylesProvider>
        <DashboardTable
            data={rowsData}
            columns={columns}
            sorting={sortedBy}
            setSorting={setSortedBy}
            resizeMode="onChange"
            isLoading={isLoading}
            expandedView={expanded}
            tableHeight={expanded ? 'calc(100vh - 164px)' : '100%'}
            pagination={{
              ...pagination,
              totalPagination: data?.pagination?.pages || 1,
            }}
            setPagination={setPagination}
            handleRouteUpdate={pageChange}
            enableSelection
            stickyHeaders={expanded ? [] : ['select', 'name']}
            rowSelection={rowselection}
            setRowSelection={setRowSelection}
            emptyText={{message: 'No users match the current filters.'}}
            tableWidth='100%'
        />
      </StylesProvider>
    </UserTableWrapper>
  );
};

export default memo(UserList);
