import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import $ from 'jquery';
import { Layout } from 'antd';
import { getFilterPropertyRemoteData } from 'redux/actions/filter';
import { fetchPlanHatApi } from 'redux/actions/common';
import {
  getUserSortedList,
  useUserList,
} from 'components/features/users/hooks/useUserItem';
import useEventUserProperties from 'hooks/useEventUserProperties';
import { goToPage } from 'components/shared/Pagination';
import styled from 'styled-components';
import { removeUxCamCustomProperty } from 'components/common/ColumnUpdate/utils';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { useIsAppType } from 'hooks/useIsAppType';
import { useIsUserV2 } from 'hooks/useUserV2Filter';
import { getFilterListWithActivityFilterCheck, isValidActivityFilterSegment } from 'Utils/helpers/activityFilterUtils';
import UserPageNew from './UserPageNew';

const { Content } = Layout;

const ContentWrapper = styled(Content)`
  pointer-events: ${( {isGlobalFilterVisible}) => isGlobalFilterVisible ?  `none` : ''};
`

const User = () => {
  const {
    urlReducer: urlQ,
    appFilter: {
      user: { segment: filters, activityFilterList },
      dateSegment,
      fetchProperty,
    },
    currentAppReducer: currentApp,
} = useSelector((state) => state);
    const isUserV2 = useIsUserV2();
    const userProperties = fetchProperty.user_custom_property.data || [];

    // * CX-1876 Only available for iceberg user
    const filterWithUserSessionActivity = useMemo(() =>
        getFilterListWithActivityFilterCheck(activityFilterList, filters, isUserV2),
        [filters, isUserV2, activityFilterList])

   

    const [delay, setDelay] = useState(true);

    // * CX-1876: 700ms delay to avoid api being called unnecessarily
    useEffect(() => {
        const apiFlagTimeout = setTimeout(() => {
            setDelay(false);
        }, 700); 

        return () => clearTimeout(apiFlagTimeout);
    }, []); 

    // * CX-1876
    const enableUserList = useMemo(() => {
        if(delay) return false ; // * disable till delay is true
        return isValidActivityFilterSegment(activityFilterList)
    }, [delay, activityFilterList])

  const { megaDropdownVisible, megaBottomDropdownVisible } = useSelector(
    (state) => state.megaFilterReducer
  )

  const dispatch = useDispatch();
  const {
    parentType,
    appId,
    userpage,
    starttime,
    uxcamuserid,
    autoplay,
    sessionid,
    eventid,
  } = urlQ;
  const [orderBy, setOrderBy] = useState([]);
  const [isMounted, componentMountToggler] = useState(false)

  const isGlobalFilterVisible = useMemo(() => megaDropdownVisible || megaBottomDropdownVisible, [megaDropdownVisible, megaBottomDropdownVisible])

  const userProperty = useMemo(
    () => ({
      attribute: 'user_custom_property',
      filter: [],
      search: '',
      dropdownLimit: 501,
      date_range: dateSegment,
    }),
    [dateSegment]
  );

  const sortByVal = useCallback((sort) => {
    const { id, desc } = sort()[0];
    const isCustomUserProperty = userProperties.includes(removeUxCamCustomProperty(id));
    setOrderBy([
      {
        id,
        desc,
        ...isCustomUserProperty && { isCustomUserProperty },
      }
    ])
  }, [userProperties])

  const appid = appId || currentApp['_id']
  let usersListReqBody = ''
  try {
    usersListReqBody = JSON.parse(localStorage.getItem('usersListReqBody'))
  } catch (err) {
    // silent fail
  }
  const isWebApp = useIsAppType( 'web' );
  const listReq = useMemo(
    () => {
        
    const payload =  {
      appid,
      page: userpage ? +userpage : 1,
      ...((orderBy?.length || usersListReqBody?.orderBy) && {
        orderBy: orderBy?.length ? [{
          sortName: orderBy[0]?.id || 'last_seen',
          sortOrder: orderBy[0]?.desc ? 'desc' : 'asc',
          ...orderBy[0]?.isCustomUserProperty && { isCustomUserProperty: true }
        }] : usersListReqBody?.orderBy,
      }),
      filters:filterWithUserSessionActivity,
      webApp: isWebApp,
      date_range: dateSegment
    }
    isUserV2 && delete payload.date_range
    return payload
},
    [appid, userpage, orderBy, usersListReqBody?.orderBy, filterWithUserSessionActivity, isWebApp, dateSegment, isUserV2]
  );
  
  useEffect(() => {
    try {
      localStorage.setItem('usersListReqBody', JSON.stringify(listReq))
    } catch (err) {
      // silent fail
    }
  }, [listReq])
  const {
    data: userList,
    refetch,
    isRefetching,
    isLoading,
  } = useUserList(listReq, '', enableUserList);
  const data = useMemo(() => userList?.data?.data || [], [userList]) 
  const resetPageDataWithApiCall = async () => {
    refetch();
    dispatch(
      getFilterPropertyRemoteData(userProperty)
    );
  };

  useEffect(() => {
    if (!['usersList'].includes(parentType)) return;
    const payload = {
      appid: appId,
      filters,
      date_range: dateSegment
    };
  }, [appId, filters.length, dateSegment, parentType, filters]);

  useEventUserProperties()

  const removeClass = () => {
    if ($('.session-detail-page').length) {
      $('.wrapper-contracts').removeClass('session-detail-page');
    }
  };

  const handleSortByOrder = useCallback((order) => {
    const isCustomUserProperty = userProperties.includes(removeUxCamCustomProperty(order[0]?.id));
    const sortedBody = {
      appid: appId,
      date_range: dateSegment,
      filters,
      table: 'userTable',
      orderBy: [{
        sortName: order[0]?.id,
        sortOrder: order[0]?.desc ? 'desc' : 'asc',
        ...isCustomUserProperty && { isCustomUserProperty }
      }],
      page: 1,
      webApp: isWebApp,
    };
    getUserSortedList(sortedBody).then(() => refetch());
  }, [appId, dateSegment, filters, isWebApp, refetch, userProperties]);

  useEffect(() => {
    if (!['usersList'].includes(parentType)) return;
    removeClass();
    dispatch(fetchPlanHatApi({ action: 'Entered users page' }));
  }, []);

  const callRedirectPage = () => {
    listReq.page = 1;
    refetch(listReq);
    goToPage({
        page: 1,
        appId,
        sessionid,
        autoplay,
        filters,
        eventid,
        parentType,
        starttime,
        expanded: false,
        uxcamuserid,
      });
  };
  useEffect(() => {
    if (orderBy?.length) {
      callRedirectPage()
      handleSortByOrder(orderBy);
    }
  }, [orderBy]);
  useEffect(() => {
    isMounted && callRedirectPage();
  }, [filters]);

  useEffect(() => {
    componentMountToggler(true);
    return () => {
      componentMountToggler(false);
    };
  }, []);

  const component = (
    <UserPageNew
      userData={data}
      loading={isRefetching || isLoading || delay}
      orderBy={orderBy}
      handleSortByOrder={sortByVal}
      resetPageDataWithApiCall={resetPageDataWithApiCall}
      key={parentType}
    />
  )
  return <ContentWrapper isGlobalFilterVisible={isGlobalFilterVisible}>{component}</ContentWrapper>
};
export default User;
