/* eslint-disable react/jsx-props-no-spreading */
import React from 'react';
import styled from 'styled-components';
import { useSelector } from 'react-redux';
import { Tooltip } from 'antd';
import Cookies from 'universal-cookie'
import { useQueryClient } from 'react-query';

import MarkLabelCell from 'components/common/MarkLabelCell';
import { useCustomLabelApi } from 'hooks/useCustomLabels';

const browserCookies = new Cookies()

const Wrapper = styled.div`
  width: 100%;
  display: flex;
  align-items: center;
  gap: 14px;

  #outside-icon-box {
    padding-left: 0;

    .ant-badge-count {
      display: none;
    }
  }
  // background-color: ${props => props?.isActive ? '#f5f5f5' : ''};
`;

const UnreadIndicator = styled.div`
  height: 6px;
  width: 6px;
  border-radius: 50%;
  background-color: ${({ unread }) => (unread ? '#DC4F44' : '#D0D2D7')};
`;

const Icons = styled.div`
  display: flex;
  flex-direction: column;
  justify-content: center;
`;

const LabelIconWrapper = styled.div`
  position: relative;
`;

const CountLabel = styled.div`
  position: absolute;
  top: -2px;
  right: -5px;
  height: 13px;
  width: 13px;
  padding: 4px;
  font-size: 0.5rem;
  color: #ffffff;
  background-color: #5D97FF;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  pointer-events: none;
`;

const TableRowCheckCell = ({ row }) => {
  const uxcamuserid = row?.original?.uxcamuserid;
  const customLabel = row?.original?.customLabel;
  const isUserViewed = row?.original?.isViewed;
  const queryClient = useQueryClient();
  const { markUserLabel } = useCustomLabelApi();

  const { currentAppReducer, urlReducer: urlQuery } = useSelector((state) => state);
  const { _id } = currentAppReducer;
  const cookieFromAdmin = browserCookies.get('loggedInFromAdminDashboard')


  const handleIndicatorClick = async () => {
    let userQueryKey = ''
    try {
      userQueryKey = ['userList', JSON.parse(localStorage.getItem('usersListReqBody'))]
    } catch (err) {
      // silent fail
    }
    if (row?.original?.uxcamuserid && cookieFromAdmin !== '1'){
      const payload = {
        customLabelName: 'isViewed',
        isTagged: !isUserViewed,
        labelType: 'user',
        uxcamuserIds: [row.original.uxcamuserid],
        appid: _id,
        debugSource: 4
      };
      queryClient.setQueryData(userQueryKey, (old) => {
        const newBody = old.data.data.body.map((el) => {
          if (el.uxcamuserid === uxcamuserid) {
              return {
                  ...el,
                  isViewed: !isUserViewed,
              };
          }

          return el;
      });
      return {
          ...old,
          data: {
              ...old.data,
              data: {
                  ...old.data.data,
                  body: newBody,
              },
          },
      };
    });
      markUserLabel(payload);
    }
  };

  return (
    <Wrapper isActive={urlQuery?.uxcamuserid === uxcamuserid}>
      <Tooltip
        placement="top"
        title={!isUserViewed ? 'Mark as read' : 'Mark as unread'}
      >

        <UnreadIndicator unread={!isUserViewed} onMouseDown={handleIndicatorClick} />

      </Tooltip>
        <input
        type="checkbox"
        aria-label="Select row"
        {...{
          checked: row.getIsSelected(),
          indeterminate: row.getIsSomeSelected(),
          disabled: !row.getCanSelect(),
          onChange: row.getToggleSelectedHandler(),
        }}
      />
      <Icons>
        <LabelIconWrapper>
          <MarkLabelCell
            data={row?.original}
          />
          {customLabel?.length > 0 && (
            <CountLabel>{customLabel.length}</CountLabel>
          )}
        </LabelIconWrapper>
      </Icons>
    </Wrapper>
  );
};

export default TableRowCheckCell;
