import React, { useState, useEffect, useMemo, useCallback } from 'react';

import {
  EyeInvisibleOutlined,
  EyeOutlined,
} from '@ant-design/icons';
import CheckMarkIcon from 'public/static/sessions/checkmark.svg';
import { Dropdown, Button } from 'antd';
import { useSelector, useDispatch } from 'react-redux';
import { invert, findLastIndex } from 'lodash';

import { addSessionId, addUserId } from 'redux/actions/common';
import { addSegmentV2 } from 'redux/actions/filter';
import { trackPageViews } from 'redux/actions/trackingReport';
import { QuickFilterSVG } from 'components/svg_files';
import useCustomLabels from 'hooks/useCustomLabels';

import findIndex from 'lodash/findIndex';
import LabelsDropdownOverlay from '../LabelsDropdownOverlay';
import { ActionButton, HeaderContainer } from './styles';

const entity = {
  sessionsList: 'sessions',
  aiSessionsList: 'sessions',
  usersList: 'users',
};

const preDefined = [
  'rageTap',
  'video',
  'session_with_notes',
  'viewed',
  'crashed',
  'unviewed',
];


const HeaderButton = ({ icon, title, onClick, selected }) => {
  const Icon = useMemo(
    () =>
      selected ? (
        <CheckMarkIcon />
      ) : (
        icon
      ),
    [selected, icon]
  );
  return (
    <ActionButton onClick={(e) => {
        e.stopPropagation();
        onClick();
    }}>
      {Icon}
      {title}
    </ActionButton>
  );
};

