const TopSessionFilter = (props) => {
  const dispatch = useDispatch();

  const { urlReducer: urlQuery,
  } =
    useSelector((state) => state);
  const { session, user } = useSelector((state) => state.appFilter);
  const sessionSegment = session.segment;
  const userSegment = user.segment;
  const parenttype = urlQuery.parentType;

  const { children, loadTable } = props;

  const {
    megaFilteredSessionLabels,
    filteredUserLabels,
    labelSearch,
    setLabelSearch,
    resetSearch,
    compareLabels
  } = useCustomLabels();
  const customLabels = useMemo(
    () =>
      parenttype === 'usersList' ? filteredUserLabels : megaFilteredSessionLabels,
    [parenttype, filteredUserLabels, megaFilteredSessionLabels]
  );
  const [selectedCustomLabelTab, setSelectedCustomLabelTab] = useState('user');

  const [selectedMenu, setSelectedMenu] = useState([]);
  
  const viewKeyMap =
    [ 'sessionsList', 'aiSessionsList' ].includes( parenttype ) ? 'session_is_viewed' : 'user_is_viewed';
  const keyMappedObject = {
    unviewed: viewKeyMap,
    viewed: viewKeyMap,
    video: 'session_has_video',
    session_with_notes: 'session_with_notes',
    crashed: 'session_crashed',
  };

  const handleFilter = useCallback(({ key }) => {
    let segment;
    let newSelected = [...selectedMenu];
    if ([ 'sessionsList', 'aiSessionsList' ].includes( parenttype )) {
      dispatch(addSessionId([]));
      let segmentValue = sessionSegment || [];
      const newValue = key !== 'rageTap' ? key : 'rageTap';
      const oldSegmentValue = [ ...segmentValue ];

      if (!newSelected.includes(newValue)) {
        newSelected = [...newSelected, newValue];
        setSelectedMenu(newSelected);
        if (key !== 'rageTap') {
          if (preDefined.includes(key)) {
            segment = {
              attribute: keyMappedObject[key],
              operator: 'equal',
              table: 'session',
              value: key !== 'unviewed' ? 'True' : 'False',
            };
          } else {
            segment = {
              attribute: 'custom_label',
              operator: 'has_any',
              value: [key],
              table: 'session',
            };
          }
        } else
          segment = { attribute: 'event_name', operator: 'in', value: [key], table: 'event' };
        segmentValue.push(segment);
        dispatch(
          trackPageViews(null, {
            eventName: 'apply_quick_filter',
            track_type: 'event',
            eventProperty: {
              type: preDefined.includes(key) ? 'predefined' : 'custom_label',
              name: key,
              featureFlagQuickbar: false,
              oldSetting: oldSegmentValue,
              newSetting: segmentValue,
            },
          })
        );
        dispatch(addSegmentV2(segmentValue, 'session-filter'));
        loadTable();
      } else {
        if (key !== 'rageTap') {
          const labelKey = keyMappedObject[key];
          if (!preDefined.includes(key)) {
            segmentValue = sessionSegment.filter((obj) => obj.value[0] !== key);
          } else if (labelKey !== 'session_is_viewed') {
            segmentValue = sessionSegment.filter(
              (obj) => obj.attribute !== labelKey
            );
          } else {
            const operator = key === 'unviewed' ? 'False' : 'True';
            const objIndex = findLastIndex(sessionSegment, {
              attribute: keyMappedObject[key],
              value: operator,
            });
            segmentValue = sessionSegment.filter(
              (obj, index) => index !== objIndex
            );
          }
        } else {
          segmentValue = sessionSegment.filter(
            (obj) => obj.value[0] !== 'rageTap'
          );
        }
        dispatch(
              addSegmentV2(
                  segmentValue.length > 0 ? segmentValue : undefined,
                  'session-filter'
              )
          );
        dispatch(
          trackPageViews(null, {
            eventName: 'quick_filter_removed',
            track_type: 'event',
            eventProperty: {
              type: preDefined.includes(key) ? 'predefined' : 'custom_label',
              name: key,
              featureFlagQuickbar: false,
              oldSetting: oldSegmentValue,
              newSetting: segmentValue,
            },
          })
        );
        loadTable();
      }
    } else if (parenttype === 'usersList') {
      dispatch(addUserId([]));
      let segmentValue = userSegment || [];
      if (!newSelected.includes(key)) {
        newSelected = [...newSelected, key];
        setSelectedMenu(newSelected);
        if (key) {
          if (preDefined && preDefined.includes(key)) {
            segment = {
              attribute: keyMappedObject[key],
              operator: 'equal',
              value: key === 'unviewed' ? 'False' : 'True',
              table: 'appuser',
            };
          } else {
            segment = {
              attribute: 'user_custom_label',
              operator: 'has_any',
              value: [key],
              table: 'appuser',
            };
          }
        }
        const existingObjectIndex = findIndex(segmentValue, {
          attribute: 'user_is_viewed',
        });

        if (existingObjectIndex !== -1) {
          // Update existing object
          segmentValue[existingObjectIndex] = segment;
        } else {
          // Push new object
          segmentValue.push(segment);
        }
      } else {
        const labelKey = keyMappedObject[key];
        if (!preDefined.includes(key)) {
          segmentValue = userSegment.filter((obj) => obj.value[0] !== key);
        } else if (labelKey !== 'user_is_viewed') {
          segmentValue = userSegment.filter(
            (obj) => obj.attribute !== labelKey
          );
        } else {
          const operator = key === 'unviewed' ? 'False' : 'True';
          const objIndex = findLastIndex(userSegment, {
            attribute: 'user_is_viewed',
            value: operator,
          });
          segmentValue = userSegment.filter((obj, index) => index !== objIndex);
        }
      }
      dispatch(
            addSegmentV2(segmentValue.length > 0 ? segmentValue : [], 'user-filter')
        );
      loadTable();
    }
  }, [loadTable, parenttype, selectedMenu, sessionSegment, userSegment]);

  const handleCustomLabelTabChange = (key) => {
    setSelectedCustomLabelTab(key)
  }

  const handleLabelSearch = useCallback((e) => {
    const { value } = e.target;
    if(selectedCustomLabelTab === 'session') {
      setLabelSearch({
        ...labelSearch,
        sessionLabels: value
      })
    } else {
      setLabelSearch({
        ...labelSearch,
        userLabels: value
      })
    }
  }, [labelSearch, selectedCustomLabelTab, setLabelSearch])

  const handleVisibleChange = (visible) => {
    if (!visible) {
      resetSearch();
      filteredUserLabels?.sort((a, b) => compareLabels(selectedMenu, a, b));
      megaFilteredSessionLabels?.sort((a, b) => compareLabels(selectedMenu, a, b));
    }
  };

  useEffect(() => {
    let filterValue = [];
    if ([ 'sessionsList', 'aiSessionsList' ].includes( parenttype )) {
      if (sessionSegment && sessionSegment.length > 0) {
        sessionSegment &&
          sessionSegment.map((obj) => {
            if (
              obj.attribute !== 'event_name' &&
              obj.attribute !== 'custom_label'
            ) {
              if (
                obj.attribute === 'session_is_viewed' &&
                obj.value === 'False'
              ) {
                filterValue.push('unviewed');
              } else {
                filterValue.push(obj.attribute);
              }
            } else if (obj.attribute === 'custom_label') {
              filterValue.push(obj.value[0]);
            } else if (
              obj.attribute === 'event_name' &&
              obj.value[0] === 'rageTap'
            ) {
              filterValue.push(obj.value[0]);
            }
          });
        filterValue = filterValue.map((v) => invert(keyMappedObject)[v] || v);
        setSelectedMenu(filterValue);
      } else {
        setSelectedMenu([]);
      }
    } else if (parenttype === 'usersList') {
      if (userSegment && userSegment.length > 0) {
        userSegment &&
          userSegment.map((obj) => {
            if (obj.attribute !== 'user_custom_label') {
              if (
                obj.attribute === 'user_is_viewed' &&
                obj.value === 'False'
              ) {
                filterValue.push('unviewed');
              } else {
                filterValue.push(obj.attribute);
              }
            } else if (obj.attribute === 'user_custom_label') {
              filterValue.push(obj.value[0]);
            }
          });
        filterValue = filterValue.map((v) => invert(keyMappedObject)[v] || v);
        setSelectedMenu(filterValue);
      } else {
        setSelectedMenu([]);
      }
    }
  }, [sessionSegment, userSegment]);

  const labelTabs = useMemo(() => (
    parenttype === 'usersList' ? [
      {
          key: 'user',
          name: 'User label',
          options: filteredUserLabels, // includes filtered labels
          showSearch: true,
      }
    ] : [
      {
          key: 'session',
          name: 'Session label',
          options: megaFilteredSessionLabels, // includes filtered labels
          showSearch: true,
      },
      {
          key: 'user',
          name: 'User label',
          options: filteredUserLabels, // includes filtered labels
          showSearch: true,
      }
    ]
  ), [filteredUserLabels, megaFilteredSessionLabels, parenttype])

  const headerButtons = useMemo(
    () =>
      parenttype === 'usersList' ? (
        <>
          <HeaderButton
            icon={<EyeOutlined />}
            title={`Viewed ${entity[parenttype]}`}
            onClick={() => handleFilter({ key: 'viewed' })}
            selected={selectedMenu.includes('viewed')}
          />

          <HeaderButton
            icon={<EyeInvisibleOutlined />}
            title={`Unviewed ${entity[parenttype]}`}
            onClick={() => handleFilter({ key: 'unviewed' })}
            selected={selectedMenu.includes('unviewed')}
          />
        </>
      ) : null,
    [handleFilter, parenttype, selectedMenu]
  );

  const renderHeader = useMemo(() => (
    <HeaderContainer>
        <span className='title'>
            Filter {entity[parenttype]} by
        </span>

        {headerButtons}
    </HeaderContainer>
  ), [headerButtons, parenttype])

  return (
    <Dropdown
      overlay={
        <LabelsDropdownOverlay
          tabs={labelTabs}
          header={renderHeader}
          selectedKeys={[
            ...selectedMenu,
          ]}
          handleItemClicked={(key) => handleFilter({key})}
          handleTabChange={handleCustomLabelTabChange}
          searchInput={{
            placeholder: `Search ${selectedCustomLabelTab} label`,
            value:
              selectedCustomLabelTab === 'session'
                ? labelSearch.sessionLabels
                : labelSearch.userLabels,
            onChange: handleLabelSearch,
          }}
          hideFooter
        />
      }
      trigger={['click']}
      onVisibleChange={handleVisibleChange}
      overlayClassName="extra-table-filter"
    >
      <div className="btn-quick-filter" data-intercom-target="Quick Filter">
        <Button size="small">
          {children ||
            (urlQuery.sessionid || urlQuery.uxcamuserid ? (
              <QuickFilterSVG />
            ) : (
              'Quick filter'
            ))}
        </Button>
      </div>
    </Dropdown>
  );
};
export default TopSessionFilter;
