import React, { useState, useEffect, useMemo } from 'react'
import dynamic from 'next/dynamic'

import { useSelector, useDispatch } from 'react-redux'

import { fetchPlanHatApi } from 'redux/actions/common'

import eventsHOC from "components/features/events/hoc"
import ReactLoader from 'components/common/reactLoading'
import ScreenFlowTab from 'components/features/navigation'
import ErrorBox from 'components/common/Customary/ErrorBox'
import LoaderAdvanced from 'components/common/LoaderAdvanced';

import { useIsAppType } from 'hooks/useIsAppType'
import UserJourney from './UserJourney'
import MenuTabsUser from './MenuTabsUser'
import LocationContent from './LocationContent'
import UserCustomLabel from './UserCustomLabel'
import PropertiesContent from './PropertiesContent'
import DetailsHeaderUser from './DetailsHeaderUser'

const Wrapper = ({ children }) => (
  <div className='tab-body-wrapper'>{children}</div>
)

const keysToHideInWeb = ["Device manufacturer", "Model name", "Device class", "DPI", "Carrier Name", "Total storage", "Total memory"]

const UsersDetailsBox = ({
  urlQuery,
  userSegment,
  error,
  setLoader,
  loader,
  resetPageDataWithApiCall,
  tableData,
  ...rest
}) => {
  const dispatch = useDispatch()
  const isWebSDK = useIsAppType( 'web' )
  const { urlReducer: { uxcamuserid }, appFilter: { dateSegment }, userDetailReducer: userDetail } = useSelector(
    (state) => state)

  const userDetailData = userDetail?.data;

  const moldedUserDetail = useMemo(() => {
    const { properties } = userDetailData;
    if (isWebSDK && properties && properties["Last used device"]) {
      // filter out objects in properties["Last used device"] array that have name in keysToHideInWeb
      properties["Last used device"] = properties["Last used device"].filter(device => !keysToHideInWeb.includes(device.name))
    }
    return userDetailData
  }, [isWebSDK, userDetailData])

  const mappedComponent = {
    properties: PropertiesContent,
    location: LocationContent,
    analytics: UserJourney,
    navigation: ScreenFlowTab,
  }
  const [selectedKey, setSelectedKey] = useState('analytics')
  const handleMenuChange = (e) => {
    if (
      e.key === 'sessions' ||
      e.key === 'events' ||
      e.key === 'notification'
    ) {
      return
    }
    setSelectedKey(e.key)
    if(e.key !== 'navigation' && e.key !== 'location')
     dispatch(
       fetchPlanHatApi({
         action: `Entered ${e.key} tab user details page`,
       })
     );
  }
  const RenderComponent = mappedComponent[selectedKey]


  return (
      <LoaderAdvanced
        show={loader}
        message={<ReactLoader />}
        backgroundStyle={{
          backgroundColor: 'rgba(255,255,255, 0.5)',
        }}
      >
        <div className="userinfo-box-wrapper detail-box-wrapper">
          {userDetail?.data?.info ? (
            <>
              <DetailsHeaderUser
                userSegment={userSegment}
                resetPageDataWithApiCall={resetPageDataWithApiCall}
                labelDisplay={userDetail?.labelDisplay}
                tableData={tableData}
              />
              { userDetail?.labelDisplay &&
                <UserCustomLabel/>
              }
              <MenuTabsUser
                handleMenuChange={handleMenuChange}
                uxcamuserid={uxcamuserid}
                urlQuery={urlQuery}
                dateRange={dateSegment}
                selectedKey={selectedKey}
              />
              <Wrapper id={selectedKey}>
                <RenderComponent
                  id={selectedKey}
                  userDetails={moldedUserDetail}
                  isUserDetails
                  setLoader={setLoader}
                  loader={loader}
                  isWebSDK={ isWebSDK }
                  {...rest}
                />
              </Wrapper>
            </>
          ) : (
            error?.message && (
              <ErrorBox errorText={error.message} displayIcon isNoData />
            )
          )}
        </div>
      </LoaderAdvanced>
  )
}
export default eventsHOC(UsersDetailsBox)
