// * CX-2105
const UserButtonLabel = memo(({
    isUserStatisticsLoading,
    totalUsers
}) => {
    const [isLoading, setIsLoading] = useState(true);
    useEffect(()=>{
        let timeout = null
        if(isLoading){
            timeout = setTimeout(() => {
                if (isLoading) {
                    setIsLoading(false);
                }
            }, 3000);
        }
        return () => {
           timeout && clearTimeout(timeout);
        };
    },[isLoading])

    if(isUserStatisticsLoading || isLoading){
        return 'Loading users ...'
    }
    return totalUsers ? `${Intl.NumberFormat().format(totalUsers) || 0} users` : 'No users';
})

const UserToolbar = ({
  expanded,
  resetPageDataWithApiCall,
  headers,
}) => {
  const queryClient = useQueryClient();
  const [dropdownVisible, setDropdownVisibility] = useState(false);
  const [loading, setLoading] = useState(false);
  const [deleteModalVisible, setDeleteModalVisible] = useState(false)
  const [deleteLoading, setDeleteLoading] = useState(false)
  const quickFilterLists = [
    'user_is_viewed',
    'user_custom_label'
  ];
  const {
    urlReducer: urlQuery,
    appFilter,
    currentAppReducer: { role },
    profileReducer: user,
  } = useSelector((state) => state);
  const { uxcamuserid, appId, userpage } = urlQuery;
   const [delay, setDelay] = useState(true);

  const dispatch = useDispatch();
  const userSegment = appFilter?.user?.segment;

  const isUserAdmin = useMemo(() => role === 1, [role]);
  const { name } = user;

  let userList = ''
  try {
    userList = queryClient.getQueryData(['userList', JSON.parse(localStorage.getItem('usersListReqBody'))]);
  } catch (err) {
    // silent fail
  }
  const isUserV2 = useIsUserV2();
  const { activityFilterList } = appFilter['user'];

  const statisticsPayload = useMemo(() => {
        const filters = getFilterListWithActivityFilterCheck(
            activityFilterList,
            userSegment,
            isUserV2,
        )
        const payload = {
            appid: appId || '',
            date_range: appFilter.dateSegment,
            filters,
        }
        // * CX-1876: no need of dateRange for activity filter 
        isUserV2 && delete payload.date_range;
        return payload
  }, [activityFilterList, appFilter.dateSegment, appId, isUserV2, userSegment]);
    // * CX-1876
    useEffect(() => {
        const apiFlagTimeout = setTimeout(() => {
            setDelay(false);
        }, 700);

        return () => clearTimeout(apiFlagTimeout);
    }, []);

  const enableUserStatistics = useMemo(() => {
        if(delay) return false ; // * disable till delay is true
        if (appId) {
             // * all the config should have the value
            return isValidActivityFilterSegment(activityFilterList)
         }
         return false
     }, [delay, appId, activityFilterList])
 
// * CX-2105 - Fetching user statistics directly for beta user or user_v2 version, no need for previous date segment, no delta calculation of this implementation
  const { data: userStatistics, isFetching: isUserStatisticsLoading } = useQuery(
        ['userStatistics', statisticsPayload],
        () => UserApi.users_statistics(statisticsPayload),
        {
            enabled: enableUserStatistics,
            keepPreviousData: true,
        }
  )
  const handleUserClick = () => {
    let url = `/app/${appId}/users/list/${userpage}?`
    url = urlSegmentEncoder(url, userSegment)
    Router.push(
      `/integration?parentType=usersList&appId=${appId}&userpage=${userpage}`,
      url
    )
  };

  const deleteUser = () => {
    const identifiers = getUserIdWithDate([urlQuery?.uxcamuserid], userList?.data?.data?.body);
    setDeleteLoading(true)
    dispatch(
        deleteUserSession(
            {
              table_name: 'user',
              app_id: appId,
              requested_by_user_name: name,
              identifiers
            }
        )
    ).then(async (response) => {
      if (response.success) {
        setDeleteLoading(false)
        setDeleteModalVisible(false)
        message.success('User deleted successfully')
        // handleClose()
        await resetPageDataWithApiCall()
        Router.push(
            `/integration?parentType=usersList&appId=${urlQuery.appId}`,
            `/app/${urlQuery.appId}/users/list/1`
        )
      } else {
        setDeleteLoading(false)
        setDeleteModalVisible(false)
        message.error(response?.response?.data.error.message)
      }
    })
  }

  const handleVisibleChange = (flag) => setDropdownVisibility(flag);
  const setLoader = (value) => setLoading(value);
  const validateQuickFilter = useMemo(() => userSegment && userSegment.some(obj =>  quickFilterLists.includes(obj.attribute)), [userSegment]);

  const handleTableChange = () => {
    dispatch(applyUserCustomFilter(1, 'user', true))
  };

  return (
    <ToolbarWrapper>
      <ToolbarLeft smaller={Boolean(uxcamuserid)}>
        <UserButton
          value={!expanded ? 'button' : 'text'}
          type="button"
          onMouseDown={() => expanded ? null : handleUserClick()}
        >
          {expanded ? (
             <UserButtonLabel isUserStatisticsLoading={isUserStatisticsLoading} totalUsers={userStatistics?.data?.data?.totalUsers}/>
          ) : (
            <>
              <ArrowLeftIconSvg /> User list{' '}
            </>
          )}
        </UserButton>
      </ToolbarLeft>
      <ToolbarRight isUserAdmin={isUserAdmin}>
        {expanded ? (
          <>
            <TopSessionFilter loadTable={handleTableChange} >
              { validateQuickFilter && userSegment?.length ? <QuickFilterIcon/> : <QuickFilterSVGGrey/> } Quick filter
            </TopSessionFilter>
            <Dropdown
              overlayClassName="column-edit-dropdown"
              className="dropdown-btn"
              trigger={['click']}
              onVisibleChange={handleVisibleChange}
              visible={dropdownVisible}
              overlay={
                <LoaderAdvanced
                  show={loading}
                  message={<LoaderInfo />}
                  backgroundStyle={{ backgroundColor: 'rgba(0, 0, 0, 0.0)' }}
                >
                   <ColumnUpdate
                     type="user"
                     appid={appId}
                     dropdownVisible={dropdownVisible}
                     setLoading={setLoader}
                     setDropdownVisibility={setDropdownVisibility}
                     headers={headers} 
                     showAddCustomUserButton                     />
                </LoaderAdvanced>
              }
            >
              <Button>
                <ColumnIconSVG />
              </Button>
            </Dropdown>
            <UsersDownloadCSV />
          </>
        ) : (
            <>
              <Popover content='Delete user' overlayClassName='custom-popover'>
                <StyleDeleteButton
                    icon={<DeleteOutlined />}
                    onClick={() => setDeleteModalVisible(true)}
                />
              </Popover>
              <Tooltip overlayClassName='custom-popover' title='Close'>
                <StyleCloseButton
                    icon={<CloseIcon />}
                    onMouseDown={handleUserClick}
                />
              </Tooltip>
            </>
        )}
      </ToolbarRight>
      <DeleteSessionBox
          title="Delete User?"
          content="Do you want to delete this user? This action is irreversible."
          onOk={deleteUser}
          onCancel={() => setDeleteModalVisible(false)}
          deleteLoading={deleteLoading}
          deleteModalVisible={deleteModalVisible}
      />
    </ToolbarWrapper>
  );
};

export default memo(UserToolbar);
