import React, { memo, useCallback, useEffect, useMemo, useState } from "react";
import { Button, Dropdown } from "antd";
import CalendarIcon from 'public/static/customisable-dashboard/calendar.svg'
import styled from 'styled-components';
import DateRangePicker from 'dashboard-builder/dist/cjs/DateRangePicker';
import { currentTimeZone, datePresetsAbsolute, getDisplayRangeDate } from "Utils/DateConversion/dateConversionUtils";

const ButtonWrap = styled(Button)`
  display: flex;
  align-items: center;
  border-radius: 4px;
  font-size: 13px;
  font-weight: 500;
  border: 1px solid rgb(192, 202, 217) !important;
  svg {
    margin: 0 10px 0 0;
  }
`

const UserDetailCalendar = ({ isUserJourney, defaultDateRange, changeDateChange }) => {
  const [open, setOpen] = useState(false)
  const handleClose = useCallback(() => setOpen(false), []);

  const value = useMemo(() => {
    const now = new Date()
    const from = new Date()
    from.setDate(now.getDate() - 30)

    const { value: { lower, upper }, tz, attribute, labelId } = defaultDateRange;
    return {
      from: new Date(lower) || from,
      to: new Date(upper) || now,
      timezone: tz || currentTimeZone,
      timezoneOffset: 0,
      source: attribute.toUpperCase() || 'UPLOAD_TIME',
      preset: labelId || '',
    }
  }, [defaultDateRange]);

  const [dateRange, setDateRange] = useState(value);
  const { from, to, timezone, preset: selectedLabelId } = dateRange || {};

  useEffect(() => {
    setDateRange(value)
  }, [value])

  const handleChange = useCallback((newRange, preset) => {
    const { from: newRangeFrom, to: newRangeTo, timezone: newRangeTz } = newRange; 
    const { id: labelId } = preset || {};

    const utcRangeFrom = newRangeFrom.toISOString();
    const utcRangeTo = newRangeTo.toISOString();

    setOpen(false);
    
    if (isUserJourney) {
      changeDateChange({
        attribute: (newRange.source).toLowerCase(),
        operator: "between_dates",
        value: {
          lower: utcRangeFrom,
          upper: utcRangeTo
        },
        tz: newRangeTz,
        labelId
      })
    }
    
  }, [changeDateChange, isUserJourney]);

  const fromDate = useMemo(() => getDisplayRangeDate(from, timezone), [from, timezone]);

  const toDate = useMemo(() => getDisplayRangeDate(to, timezone), [to, timezone]);

  const dateLabel = useMemo(() => datePresetsAbsolute.find(item => item.id === selectedLabelId), [selectedLabelId]);

  const btnLabel = useMemo(() => {
    if(open) {
      return `${fromDate} - ${toDate}`;
    }
    return dateLabel?.label || `${fromDate} - ${toDate}`},
  [open, dateLabel, fromDate, toDate])

  return (
    <Dropdown
      trigger={['click']}
      onVisibleChange={setOpen}
      visible={open}
      destroyPopupOnHide
      overlay={(
        <DateRangePicker
          enableSource
          onClose={handleClose}
          value={dateRange}
          onChange={handleChange}
        />
      )}
    >
      <ButtonWrap><CalendarIcon /> {btnLabel}</ButtonWrap>
    </Dropdown>
  )
}

export default memo(UserDetailCalendar);