/* eslint-disable no-nested-ternary */
import React, { useState, useEffect, useMemo } from 'react'
import { useDispatch } from 'react-redux'
import {CaretDownOutlined, CaretUpOutlined} from "@ant-design/icons";
import { Skeleton, Tooltip } from 'antd';
import { map } from 'underscore'
import Link from 'next/link'
import cs from 'classnames'
import { v4 } from 'uuid'
import { RedirectLinkSVG } from 'components/svg_files'
import { fetchPlanHatApi } from 'redux/actions/common';
import { useIsAppType } from 'hooks/useIsAppType';

const isValid = (value) =>
  value ? (!value.includes('nan')) : false
const isNegation = (value) => value.includes('-')
const Common = ({ title, loading }) => (
    <div
      key={title}
      className={title === 'Sessions' || loading ? 'selected box' : 'box'}
    >
      <Skeleton
        key={v4()}
        active
        loading={loading}
        paragraph={{
          rows: 1,
        }}
      >
        <span className='box-title'>{title}</span>
        <br />
        <span className='stat'>Error</span>
        <br />
        <span className='value'>
          <span className='icon-box'>{/* <Icon type='error' /> */}</span>
        </span>
      </Skeleton>
    </div>
  )
const LoadingDataOrError = (props) => (
    <>
      <Wrapper boxWrapperTitle="Engagement" isWebSDK={ props.isWebSDK }>
        {map(['Sessions', 'Screen visits', 'Events'], (v) => <Common title={v} key={v} {...props} />)}
      </Wrapper>
      <Wrapper boxWrapperTitle="Frustration" isWebSDK={ props.isWebSDK }>
        {map( props.isWebSDK ? ['Rage taps'] : ['Total Crash', 'Rage taps', 'UI Freezes'], (v) => <Common title={v} key={v} {...props} />)}
      </Wrapper>
    </>
  )
const NormalCase = ({ boxWrapperTitle, percentage_change_string }) => {
  const isNA = percentage_change_string === "N/A"
  return (
    <Tooltip title={ isNA ? "Baseline value is missing, unable to calculate the change percentage." : undefined } placement='bottom'>
      <span
        className={cs(
          'value',
          isNA
            ? 'value-grey'
            :
          boxWrapperTitle === 'Engagement'
            ? isNegation(percentage_change_string)
              ? 'value-red'
              : 'value-green'
            : isNegation(percentage_change_string)
            ? 'value-green'
            : 'value-red'
        )}
        style={ { width: "fit-content" } }
      >
        <span className='icon-box'>
          {isNegation(percentage_change_string) ? <CaretDownOutlined /> : <CaretUpOutlined />}
        </span>
        {percentage_change_string}
      </span>
    </Tooltip>
  )
}
const PreviousPeriodZeroCase = ({
  boxWrapperTitle,
  value_this_period_number,
  value_previous_period_number,
  isPreviousPeriodStringValid,
  value_previous_period_string,
}) => {
  const isLessPerviousPeriod =
    value_this_period_number < value_previous_period_number
  return (
    <span
      className={cs(
        'value',
        value_this_period_number !== value_previous_period_number
          ? boxWrapperTitle === 'Engagement'
            ? isLessPerviousPeriod
              ? 'value-red'
              : 'value-green'
            : isLessPerviousPeriod
            ? 'value-green'
            : 'value-red'
          : ''
      )}
    >
      {value_previous_period_number !== value_this_period_number && (
        <span className='icon-box'>
          {isLessPerviousPeriod ? <CaretDownOutlined /> : <CaretUpOutlined />}
        </span>
      )}
      <span className="prev-value">
        {isPreviousPeriodStringValid
          ? `Prev: ${value_previous_period_string}`
          : `Prev: 0`}
      </span>
    </span>
  );
}
const Wrapper = ({ children, boxWrapperTitle, isWebSDK = false }) => (
    <div className='journey-tab-box' data-is-web={isWebSDK}>
      <h3 className='box-wrapper-title'>{boxWrapperTitle}</h3>
      <div className='box-wrapper'>{children}</div>
    </div>
  )
const SingleBox = ({
  percentage_change_string,
  value_this_period_string,
  value_previous_period_string,
  value_this_period_number,
  value_previous_period_number,
  boxTitle,
  box_key,
  setActive,
  selected,
  boxWrapperTitle,
  urlData,
  loader,
}) => {
  if (!value_previous_period_number) value_previous_period_number = 0
  if (!value_this_period_number) value_this_period_number = 0
  const isPreviousPeriodStringValid = isValid(value_previous_period_string)
  const isPeriodStringValid = isValid(value_this_period_string)
  const isPerviousPeriodZero = value_previous_period_number === 0
  return (
    <div
      onClick={() => setActive(box_key)}
      className={`box ${selected === box_key || loader ? 'selected' : ''}`}
      data-intercom-target={`Cards ${boxTitle}`}
    >
      <Skeleton
        key={v4()}
        active
        loading={loader}
        paragraph={{
          rows: 1,
        }}
      >
        <span className='box-title'>{boxTitle}</span>
        <br />
        <span className='stat'>
          {isPeriodStringValid ? value_this_period_string : 0}
        </span>
        <br />
        {isPerviousPeriodZero ? (
          <PreviousPeriodZeroCase
            boxWrapperTitle={boxWrapperTitle}
            value_this_period_number={value_this_period_number}
            value_previous_period_number={value_previous_period_number}
            isPreviousPeriodStringValid={isPreviousPeriodStringValid}
            value_previous_period_string={value_previous_period_string}
          />
        ) : percentage_change_string ? (
          <NormalCase
            boxWrapperTitle={boxWrapperTitle}
            percentage_change_string={percentage_change_string}
          />
        ) : (
          <span className="value">
            <span className='icon-box' />
          </span>
        )}
        {urlData && (
          <Link
            passHref
            href={{
              pathname: '/integration',
              query: {
                parentType: urlData.parentType,
                appId: urlData.appId,
                type: urlData.type,
                issueType: urlData.issueType,
                dateRange: urlData.dateRange,
                isSessionEventTab: true,
              },
            }}
            as={urlData.url}
            legacyBehavior
          >
            <a target='_blank' href="" className='view-btn' rel="noreferrer">
              <span
                onClick={(e) => {
                  e.stopPropagation()
                }}
              >
                View <RedirectLinkSVG />
              </span>
            </a>
          </Link>
        )}
      </Skeleton>
    </div>
  )
}
const Category = ({
  data,
  boxWrapperTitle,
  selected,
  setActive,
  loader,
  urlReducer,
  dateRange,
}) => {
  const isWebSDK = useIsAppType( 'web' )
  const getUrl = (page, filter) => {
    const { attribute, labelId, value: { lower, upper}, tz } = dateRange;
    const lowerDate = JSON.stringify(lower);
    const upperDate = JSON.stringify(upper);
    // const dateRangeQuery=`{"o":"between_dates","v":{"lower":${JSON.stringify(dateRange?.value?.lower)},"upper":${JSON.stringify(dateRange?.value?.upper)}}`
    const dateRangeQuery = () => `${attribute}={"o":"between_dates","v":{"lower":${lowerDate},"upper":${upperDate}}, "lb":"${labelId || ''}","tz":"${tz || 'UTC'}"}&uxcamuserid={"o":"in","v":["${urlReducer.uxcamuserid}"]}`
  
    const url = `/app/${
      urlReducer.appId
    }/${page}/list/1?${dateRangeQuery()}${filter ? `&${filter}&` : '&'}isSessionEventTab=${true}`
    return url
  }
  const mappedRedirectData = {
    total_engagement: {
      url: getUrl('sessions'),
      parentType: 'sessionsList',
      type: 'session',
    },
    // 'screen_count': {
    //   url: getUrl('heatmaps'),
    //   parentType: 'screensList',
    //   type: 'screen',
    // },
    event_count: {
      url: getUrl('events'),
      parentType: 'eventsList',
      type: 'event',
    },
    crash_count: {
      url: getUrl('sessions', 'session_crashed={"o":"equal","v":"True","tb":"session"}'),
      parentType: 'sessionsList',
      type: 'session',
    },
    rage_count: {
      url: getUrl('sessions', 'event_name={"o":"in","v":["rageTap"],"tb":"event"}'),
      parentType: 'sessionsList',
      type: 'session',
    },
    ANR_count: {
      url: getUrl('sessions', 'event_name={"o":"in","v":["UI Freeze"],"tb":"event"}'),
      parentType: 'sessionsList',
      type: 'session',
    },
  }
  return (
    <Wrapper boxWrapperTitle={boxWrapperTitle} isWebSDK={isWebSDK}>
      {data.map((value, index) => {
        const {
          value_previous_period_string,
          value_this_period_string,
          value_this_period_number,
          value_previous_period_number,
          percentage_change_string,
          box_name,
          box_key,
        } = value
        return (
          <SingleBox
            key={box_name}
            percentage_change_string={percentage_change_string}
            value_previous_period_string={value_previous_period_string}
            value_this_period_string={value_this_period_string}
            value_this_period_number={value_this_period_number}
            value_previous_period_number={value_previous_period_number}
            selected={selected}
            boxTitle={box_name}
            box_key={box_key}
            setActive={setActive}
            boxWrapperTitle={boxWrapperTitle}
            urlData={mappedRedirectData[box_key]}
            loader={loader}
          />
        )
      })}
    </Wrapper>
  )
}
const UserJourneyInfoBoxes = ({
  loader,
  dateRange,
  urlReducer,
  userJourneyBoxes,
  dropdown_options,
  setSelectedCategory,
}) => {
  const dispatch = useDispatch()
  const isWebSDK = useIsAppType( 'web' );
  const mappedObj = {
    total_engagement: 'total_engagement',
    screen_count: 'screen_count',
    event_count: 'event_count',
    crash_count: 'crash_rate',
    rage_count: 'rage_rate',
    ANR_count: 'ANR_rate',
  }
  const [selected, setActive] = useState('total_engagement')
  const GrpByOptByKey = () => {
    const selectedKey = mappedObj[selected]
    if (dropdown_options) {
      const selectedCategory = dropdown_options && dropdown_options[selectedKey]
      setSelectedCategory(selectedCategory)
      dispatch(fetchPlanHatApi({ action: 'Clicked on user journey tab', info: { 'tab name':  selectedCategory.box_name }}))
    }
  }

  const userJourneyBoxData = userJourneyBoxes?.data?.boxes

  const moldedUserJourneyData = useMemo(() => {
    if (userJourneyBoxData && isWebSDK) {
      return {
        ...userJourneyBoxData,
        Frustration: userJourneyBoxData.Frustration.filter((box) => box.box_key === 'rage_count'),
      }
    }
    return userJourneyBoxData
  }, [userJourneyBoxData, isWebSDK])

  useEffect(() => {
    dropdown_options && GrpByOptByKey()
  }, [selected, dropdown_options])
  return (
    <div className='journey-box-wrapper'>
      {userJourneyBoxes ? (
        userJourneyBoxes.data ? (
          map(moldedUserJourneyData, (data, key) => (
              <Category
                key={v4()}
                boxWrapperTitle={key}
                data={data}
                setActive={setActive}
                selected={selected}
                loader={loader}
                urlReducer={urlReducer}
                dateRange={dateRange}
              />
            ))
        ) : (
          <LoadingDataOrError isWebSDK={ isWebSDK } loading={false} />
        )
      ) : (
        <LoadingDataOrError isWebSDK={ isWebSDK } loading />
      )}
    </div>
  )
}

export default UserJourneyInfoBoxes
