import React, { useMemo, useCallback, useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { contains } from 'underscore';
import { useQueryClient } from 'react-query';

import { displayUserLabel } from 'redux/actions/common';
import CommonCustomLabel from 'components/common/DetailPageCustomLabel';
import {gotUserDetail} from 'redux/actions/userList/actionObjects'
import { trackPageViews } from 'redux/actions/trackingReport';
import useCustomLabels, { useCustomLabelApi } from 'hooks/useCustomLabels';

const UserCustomLabel = () => {
  const queryClient = useQueryClient();
  const dispatch = useDispatch();

  const {
    urlReducer: urlQuery,
  } = useSelector((state) => state);

  const { userLabels: customLabels } = useCustomLabels();
  const {addUserLabel, markUserLabel} = useCustomLabelApi();

  const {uxcamuserid: userId } = urlQuery;


  const { currentAppReducer, userDetailReducer } = useSelector((state) => state);
  const { _id: appid } = currentAppReducer;
 
  const { data: userDetails } = userDetailReducer;
  const { customLabel} = userDetails;
  const [labelOnUserDetail, setLabelsOnUserDetail] = useState(customLabel || []);

  const handleCloseLabel = () => {
    dispatch(displayUserLabel(false));
  };

  useEffect(() => {
    setLabelsOnUserDetail(customLabel);
  }, [customLabel, userDetails]);

  const updateUserDetail = (labelName) => {
    const newUserDetail = {...userDetails}
    if(labelOnUserDetail?.includes(labelName)){
      const updatedUserCustomLabel = labelOnUserDetail?.filter(label => label !== labelName)
      newUserDetail.customLabel = updatedUserCustomLabel
      setLabelsOnUserDetail(updatedUserCustomLabel)
    } else {
      setLabelsOnUserDetail([...labelOnUserDetail, labelName])
      newUserDetail.customLabel = [...labelOnUserDetail, labelName]
    }
    dispatch(gotUserDetail(newUserDetail))
  }
  let usersListPayloadOnUserDetail = ''
  try {
    usersListPayloadOnUserDetail = JSON.parse(localStorage.getItem('usersListReqBody'))
  } catch (err) {
    // silent fail
  }
  const userQueryKey = useMemo(() => ['userList', usersListPayloadOnUserDetail], [usersListPayloadOnUserDetail])

  const handleUserDetailMarkLabel = useCallback((data) => {
    const labelName =  data.customLabelName
    const markValue =  data.isTagged
    const payload = {
      ...data,
      uxcamuserIds: [userId],
      labelType: 'user',
      appid,
    }

    if(labelName){
     updateUserDetail(labelName);
     markUserLabel(payload);
     dispatch(
       trackPageViews(null, {
         eventName: markValue ? 'add_label' : 'remove_label',
         track_type: 'event',
         eventProperty: {
           'label name': labelName,
           'user ids': [userId],
           'label_type': 'user',
         },
       })
     );
     queryClient.setQueryData(userQueryKey, (old) => {
        const bodyCopy =  [...old.data?.data?.body ?? []];
        const index = bodyCopy.findIndex((el) => el.uxcamuserid === userId);
        let userDetailObj = bodyCopy[index];
        const value = data.isTagged;
        if (userDetailObj?.customLabel?.indexOf(labelName) > -1) {
            if (!value) {
                const customLabelCopy = [...userDetailObj.customLabel];
                customLabelCopy.splice(customLabelCopy.indexOf(labelName), 1);
                userDetailObj = {
                    ...userDetailObj,
                    customLabel: customLabelCopy,
                };
            }
        } else if (value && userDetailObj?.customLabel) {
            userDetailObj = {
                ...userDetailObj,
                customLabel: [...userDetailObj.customLabel, labelName],
            };
        }

        return {
            ...old,
            data: {
                ...old.data,
                data: {
                    ...old.data.data,
                    body: bodyCopy?.length && bodyCopy.map((el) => {
                        if (el?.uxcamuserid === userDetailObj?.uxcamuserid) {
                            return {
                                ...el,
                                customLabel: userDetailObj?.customLabel || [],
                            };
                        }
                        return el;
                    }),
                },
            },
        };
    });
    }
  }, [userId, appid, markUserLabel, dispatch, queryClient, userQueryKey]);

  const handleLabelAddOnUser = async(data) => {
    addUserLabel(data);
    const ids = data?.uxcamuserIds || [];
    dispatch(
      trackPageViews(null, {
        eventName: 'add_label',
        track_type: 'event',
        eventProperty: {
          'label name': data?.customLabelName,
          'user ids': ids,
          'label_type': 'user',
        },
      })
    );

    queryClient.setQueryData(
       userQueryKey,
      (old) => {
        const tableData = old.data.data.body?.length ? old.data.data.body : []
        const newBody = tableData?.length && tableData.map((el) => {
          if (ids.length && ids.includes(el.uxcamuserid)) {
            return {
              ...el,
              customLabel: [...el.customLabel, data.customLabelName],
            };
          }
          return el;
        });
        return {
          ...old,
          data: {
            ...old.data,
            data: {
              ...old.data.data,
              body: newBody,
            },
          },
        };
      }
    );

    const labelName =  data?.customLabelName
    updateUserDetail(labelName)
  };

  const handleSubmit = async (labelName, labelData) => {
    const customLabelData = customLabels?.length ? [...customLabels] : [];
    const objUser = { name: labelName, icon: 'tag', usercount: 1 };
    const value = { customLabelName: labelName, labelIcon: 'tag' };
    if (labelName.length && !contains(labelData, labelName)) {
      customLabelData.push(objUser);
      customLabelData.sort((a, b) =>
        a.name.localeCompare(b.name)
      );
      const combinedUserData = {
        ...value,
        uxcamuserIds: [userId],
        appid
      };

      handleLabelAddOnUser(combinedUserData);
    }
  };

  return (
    <CommonCustomLabel
        addedLabels={labelOnUserDetail}
        handleRemoveLabel={handleUserDetailMarkLabel}
        addLabel={handleSubmit}
        handleMarkLabel={handleUserDetailMarkLabel}
        handleCloseLabel={handleCloseLabel}
        labelCountBy='usercount'
      />
  );
};

export default UserCustomLabel;
